INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35897, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "悪い結果の原因や理由。", "primary_collocate": null, "pronunciation": "せい", "ipa": "seː", "syllable_count": 2, "sentences": [{"text": "雪の所為で電車が遅れた。", "target_word": "所為", "complexity_tier": "T3", "furigana": "せい", "sentence_source": "generated"}, {"text": "遅刻を渋滞の所為にした。", "target_word": "所為", "complexity_tier": "T3", "furigana": "せい", "sentence_source": "generated"}, {"text": "疲れの所為で集中できない。", "target_word": "所為", "complexity_tier": "T3", "furigana": "せい", "sentence_source": "generated"}, {"text": "それは君の所為じゃないよ。", "target_word": "所為", "complexity_tier": "T3", "furigana": "せい", "sentence_source": "generated"}, {"text": "薬の所為で眠くなった。", "target_word": "所為", "complexity_tier": "T3", "furigana": "せい", "sentence_source": "generated"}, {"text": "道に迷ったのは地図の所為だ。", "target_word": "所為", "complexity_tier": "T3", "furigana": "せい", "sentence_source": "generated"}, {"text": "騒音の所為でよく眠れなかった。", "target_word": "所為", "complexity_tier": "T3", "furigana": "せい", "sentence_source": "generated"}, {"text": "全部私の所為です。", "target_word": "所為", "complexity_tier": "T3", "furigana": "せい", "sentence_source": "generated"}, {"text": "天気の所為にするのはやめよう。", "target_word": "所為", "complexity_tier": "T3", "furigana": "せい", "sentence_source": "generated"}, {"text": "緊張の所為で手が震えた。", "target_word": "所為", "complexity_tier": "T3", "furigana": "せい", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 悪い結果を招いた原因", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcf59757-caf5-4a24-91f4-95eaf1948046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prom