INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35892, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "経つ", "is_correct": true, "explanation": "正解：「たつ」と読む対象語。"}, {"text": "勝つ", "is_correct": false, "explanation": "「かつ」と読み、第一モーラ「た」が「か」に替わる一モーラ差。"}, {"text": "待つ", "is_correct": false, "explanation": "「まつ」と読み、第一モーラ「た」が「ま」に替わる一モーラ差。"}, {"text": "炊く", "is_correct": false, "explanation": "「たく」と読み、第二モーラ「つ」が「く」に替わる一モーラ差。"}, {"text": "竹", "is_correct": false, "explanation": "「たけ」と読み、第二モーラ「つ」が「け」に替わる一モーラ差。"}], "explanations": {"経つ": "正解：「たつ」と読む対象語。", "勝つ": "「かつ」と読み、第一モーラ「た」が「か」に替わる一モーラ差。", "待つ": "「まつ」と読み、第一モーラ「た」が「ま」に替わる一モーラ差。", "炊く": "「たく」と読み、第二モーラ「つ」が「く」に替わる一モーラ差。", "竹": "「たけ」と読み、第二モーラ「つ」が「け」に替わる一モーラ差。"}, "sentence_index": null, "correct_answer": "経つ"}, "level_3": {"options": [{"text": "経つ", "is_correct": true, "explanation": "時間が過ぎることを表す。"}, {"text": "書く", "is_correct": false, "explanation": "意味：時間は書く主体にならない。"}, {"text": "開く", "is_correct": false, "explanation": "項構造：「時間が開く」は時間の経過を表さない。"}, {"text": "洗う", "is_correct": false, "explanation": "意味：時間が何かを洗うことはない。"}], "explanations": {"経つ": "時間が過ぎることを表す。", "書く": "意味：時間は書く主体にならない。", "開く": "項構造：「時間が開く」は時間の経過を表さない。", "洗う": "意味：時間が何かを洗うことはない。"}, "sentence_index": 0, "correct_answer": "経つ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "日本に来てから一年を経つ。", "explanation": "助詞の混同：経つ時間は「が」で示し、「を」は使わない。"}, {"text": "明日、日本に来てから一年が経った。", "explanation": "アスペクトの誤り：「明日」と過去形が合わない。"}, {"text": "一年が日本に来てから経つの。", "explanation": "語順の誤り：起点の節が主語の後に割り込み不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a8a4674-0300-4d93-a215-8560fdf47e2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35892, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三年を経った。", "corrected_sentence": "三年が経った。", "error_description": "助詞の混同：経過する時間は「を」でなく「が」で示す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "経った", "is_correct": true, "explanation": "過去に三年が過ぎたことを、た形で言い切る。"}, {"text": "経って", "is_correct": false, "explanation": "て形では文が終わらない。"}, {"text": "経てば", "is_correct": false, "explanation": "条件形で後件がなく文が成立しない。"}, {"text": "経ち", "is_correct": false, "explanation": "連用形だけでは文を言い切れない。"}], "correct_form": "経った", "base_form": "経つ", "form_label": "た形（過去）", "sentence_index": 1, "explanations": {"経った": "過去に三年が過ぎたことを、た形で言い切る。", "経って": "て形では文が終わらない。", "経てば": "条件形で後件がなく文が成立しない。", "経ち": "連用形だけでは文を言い切れない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a8a4674-0300-4d93-a215-8560fdf47e2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35892, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「経つ」の主語である時間を示す。"}, {"text": "を", "is_correct": false, "explanation": "「経つ」は自動詞で「を」の目的語をとらない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段で、時間が経つ主体を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「時間に経つ」は非文。"}], "correct_answer": "が", "explanations": {"が": "「経つ」の主語である時間を示す。", "を": "「経つ」は自動詞で「を」の目的語をとらない。", "で": "「で」は手段で、時間が経つ主体を示せない。", "に": "「時間に経つ」は非文。"}, "error_tags": {"を": "object_marking", "で": "instrument", "に": "location_vs_target"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a8a4674-0300-4d93-a215-8560fdf47e2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35892, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "経つ", "is_correct": true, "explanation": "正解：「たつ」と読む対象語。"}, {"text": "打つ", "is_correct": false, "explanation": "「うつ」と読み、最初のモーラ「た」と「う」が違う。"}, {"text": "持つ", "is_correct": false, "explanation": "「もつ」と読み、最初のモーラ「た」と「も」が違う。"}, {"text": "旅", "is_correct": false, "explanation": "「たび」と読み、二番目のモーラ「つ」と「び」が違う。"}, {"text": "玉", "is_correct": false, "explanation": "「たま」と読み、二番目のモーラ「つ」と「ま」が違う。"}], "explanations": {"経つ": "正解：「たつ」と読む対象語。", "打つ": "「うつ」と読み、最初のモーラ「た」と「う」が違う。", "持つ": "「もつ」と読み、最初のモーラ「た」と「も」が違う。", "旅": "「たび」と読み、二番目のモーラ「つ」と「び」が違う。", "玉": "「たま」と読み、二番目のモーラ「つ」と「ま」が違う。"}, "sentence_index": null, "correct_answer": "経つ"}, "level_3": {"options": [{"text": "経ち", "is_correct": true, "explanation": "「経ちました」で五年が過ぎたことを表す。"}, {"text": "着き", "is_correct": false, "explanation": "意味：「着く」は瞬間的な動作で「五年」と共起しない。"}, {"text": "割れ", "is_correct": false, "explanation": "意味：「五年割れました」は意味をなさない。"}, {"text": "生まれ", "is_correct": false, "explanation": "意味：卒業後に「五年生まれる」ことはない。"}], "explanations": {"経ち": "「経ちました」で五年が過ぎたことを表す。", "着き": "意味：「着く」は瞬間的な動作で「五年」と共起しない。", "割れ": "意味：「五年割れました」は意味をなさない。", "生まれ": "意味：卒業後に「五年生まれる」ことはない。"}, "sentence_index": 6, "correct_answer": "経ち"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "楽しい時間をすぐ経つ。", "explanation": "助詞の混同：自動詞「経つ」に「を」は使えない。"}, {"text": "昨日、楽しい時間はすぐ経つ。", "explanation": "時制の誤り：「昨日」と非過去形「経つ」が合わない。"}, {"text": "一冊の時間はすぐ経つ。", "explanation": "助数詞の誤り：時間を「冊」で数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a8a4674-0300-4d93-a215-8560fdf47e2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
