INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35893, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "経ちた年月を思い出す。", "corrected_sentence": "経った年月を思い出す。", "error_description": "活用の誤り：「経つ」のた形は「経った」で、「経ちた」とは言わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "経った", "is_correct": true, "explanation": "「ころ」を修飾し、過ぎた時点を表すた形。"}, {"text": "経って", "is_correct": false, "explanation": "て形は「ころ」を直接修飾できない。"}, {"text": "経てば", "is_correct": false, "explanation": "条件形は名詞を修飾できない。"}, {"text": "経ちます", "is_correct": false, "explanation": "ます形はこの位置で名詞を修飾しない。"}], "correct_form": "経った", "base_form": "経つ", "form_label": "た形（過去）", "sentence_index": 7, "explanations": {"経った": "「ころ」を修飾し、過ぎた時点を表すた形。", "経って": "て形は「ころ」を直接修飾できない。", "経てば": "条件形は名詞を修飾できない。", "経ちます": "ます形はこの位置で名詞を修飾しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a8a4674-0300-4d93-a215-8560fdf47e2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35893, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "引っ越した時点を起点として示す。"}, {"text": "を", "is_correct": false, "explanation": "て形の後に「を」は付かない。"}, {"text": "に", "is_correct": false, "explanation": "「引っ越してに」は非文。"}, {"text": "へ", "is_correct": false, "explanation": "「引っ越してへ」は非文。"}], "correct_answer": "から", "explanations": {"から": "引っ越した時点を起点として示す。", "を": "て形の後に「を」は付かない。", "に": "「引っ越してに」は非文。", "へ": "「引っ越してへ」は非文。"}, "error_tags": {"を": "object_marking", "に": "source_vs_goal", "へ": "direction"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a8a4674-0300-4d93-a215-8560fdf47e2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35896, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "所為", "is_correct": true, "explanation": "正解：「せい」と読む対象語。"}, {"text": "席", "is_correct": false, "explanation": "「せき」と読み、第二モーラ「い」が「き」に替わる一モーラ差。"}, {"text": "線", "is_correct": false, "explanation": "「せん」と読み、第二モーラ「い」が「ん」に替わる一モーラ差。"}, {"text": "税", "is_correct": false, "explanation": "「ぜい」と読み、「せ」と「ぜ」の清濁の対立。"}, {"text": "礼", "is_correct": false, "explanation": "「れい」と読み、第一モーラ「せ」が「れ」に替わる一モーラ差。"}], "explanations": {"所為": "正解：「せい」と読む対象語。", "席": "「せき」と読み、第二モーラ「い」が「き」に替わる一モーラ差。", "線": "「せん」と読み、第二モーラ「い」が「ん」に替わる一モーラ差。", "税": "「ぜい」と読み、「せ」と「ぜ」の清濁の対立。", "礼": "「れい」と読み、第一モーラ「せ」が「れ」に替わる一モーラ差。"}, "sentence_index": null, "correct_answer": "所為"}, "level_3": {"options": [{"text": "所為", "is_correct": true, "explanation": "「雨の所為で」で中止の原因を表す。"}, {"text": "机", "is_correct": false, "explanation": "意味：机は原因にならない。"}, {"text": "歌", "is_correct": false, "explanation": "意味：雨の歌は中止の理由を表さない。"}, {"text": "紙", "is_correct": false, "explanation": "連語：「雨の紙で」は不自然。"}], "explanations": {"所為": "「雨の所為で」で中止の原因を表す。", "机": "意味：机は原因にならない。", "歌": "意味：雨の歌は中止の理由を表さない。", "紙": "連語：「雨の紙で」は不自然。"}, "sentence_index": 0, "correct_answer": "所為"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "年を所為か、すぐ疲れる。", "explanation": "助詞の混同：原因の名詞は「の」で「所為」につなぐ。"}, {"text": "一匹の所為か、すぐ疲れる。", "explanation": "助数詞の誤り：原因を「匹」で数えない。"}, {"text": "昨日、年の所為か、すぐ疲れる。", "explanation": "時制の誤り：「昨日」と非過去形「疲れる」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a8a4674-0300-4d93-a215-8560fdf47e2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
