INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35897, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "疲れの所為を集中できない。", "corrected_sentence": "疲れの所為で集中できない。", "error_description": "助詞の混同：原因は「所為で」で示す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a8a4674-0300-4d93-a215-8560fdf47e2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35897, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「所為にする」で原因を押しつけることを表す。"}, {"text": "を", "is_correct": false, "explanation": "すでに「遅刻を」があり、「所為をした」は非文。"}, {"text": "が", "is_correct": false, "explanation": "「所為がした」は非文。"}, {"text": "へ", "is_correct": false, "explanation": "「所為へした」は非文。"}], "correct_answer": "に", "explanations": {"に": "「所為にする」で原因を押しつけることを表す。", "を": "すでに「遅刻を」があり、「所為をした」は非文。", "が": "「所為がした」は非文。", "へ": "「所為へした」は非文。"}, "error_tags": {"を": "object_marking", "が": "topic_vs_subject", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "おかげ", "is_correct": true, "explanation": "「所為」が悪い結果の原因を言うのに対し、「おかげ」は良い結果の原因を言う対義語。"}, {"text": "理由", "is_correct": false, "explanation": "原因一般を表し、対の関係ではない。"}, {"text": "結果", "is_correct": false, "explanation": "原因に対する結果で、良し悪しの対ではない。"}, {"text": "原因", "is_correct": false, "explanation": "「所為」とほぼ同じ方向の語で対義語ではない。"}], "correct_answer": "おかげ", "explanations": {"おかげ": "「所為」が悪い結果の原因を言うのに対し、「おかげ」は良い結果の原因を言う対義語。", "理由": "原因一般を表し、対の関係ではない。", "結果": "原因に対する結果で、良し悪しの対ではない。", "原因": "「所為」とほぼ同じ方向の語で対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a8a4674-0300-4d93-a215-8560fdf47e2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35897, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "所為", "is_correct": true, "explanation": "正解：「せい」と読む対象語。"}, {"text": "席", "is_correct": false, "explanation": "「せき」と読み、第二モーラ「い」が「き」に替わる一モーラ差。"}, {"text": "線", "is_correct": false, "explanation": "「せん」と読み、第二モーラ「い」が「ん」に替わる一モーラ差。"}, {"text": "税", "is_correct": false, "explanation": "「ぜい」と読み、「せ」と「ぜ」の清濁の対立。"}, {"text": "礼", "is_correct": false, "explanation": "「れい」と読み、第一モーラ「せ」が「れ」に替わる一モーラ差。"}], "explanations": {"所為": "正解：「せい」と読む対象語。", "席": "「せき」と読み、第二モーラ「い」が「き」に替わる一モーラ差。", "線": "「せん」と読み、第二モーラ「い」が「ん」に替わる一モーラ差。", "税": "「ぜい」と読み、「せ」と「ぜ」の清濁の対立。", "礼": "「れい」と読み、第一モーラ「せ」が「れ」に替わる一モーラ差。"}, "sentence_index": null, "correct_answer": "所為"}, "level_3": {"options": [{"text": "所為", "is_correct": true, "explanation": "騒音が眠れなかった原因であることを表す。"}, {"text": "椅子", "is_correct": false, "explanation": "意味：椅子は原因を表さない。"}, {"text": "帽子", "is_correct": false, "explanation": "意味：騒音の帽子はない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "連語：「騒音の鉛筆で」は結びつかない。"}], "explanations": {"所為": "騒音が眠れなかった原因であることを表す。", "椅子": "意味：椅子は原因を表さない。", "帽子": "意味：騒音の帽子はない。", "鉛筆": "連語：「騒音の鉛筆で」は結びつかない。"}, "sentence_index": 6, "correct_answer": "所為"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "緊張を所為で手が震えた。", "explanation": "助詞の混同：「緊張の所為」と「の」でつなぐ。"}, {"text": "一枚の所為で手が震えた。", "explanation": "助数詞の誤り：原因を「枚」で数えない。"}, {"text": "明日、緊張の所為で手が震えた。", "explanation": "時制の誤り：「明日」と過去形「震えた」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a8a4674-0300-4d93-a215-8560fdf47e2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35897, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天気の所為をするのはやめよう。", "corrected_sentence": "天気の所為にするのはやめよう。", "error_description": "助詞の混同：「所為にする」が正しく、「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a8a4674-0300-4d93-a215-8560fdf47e2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35897, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「所為で」で遅れの原因を示す。"}, {"text": "を", "is_correct": false, "explanation": "「所為を電車が遅れた」は非文。"}, {"text": "に", "is_correct": false, "explanation": "「所為に電車が遅れた」は非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は原因を表さない。"}], "correct_answer": "で", "explanations": {"で": "「所為で」で遅れの原因を示す。", "を": "「所為を電車が遅れた」は非文。", "に": "「所為に電車が遅れた」は非文。", "へ": "方向の「へ」は原因を表さない。"}, "error_tags": {"を": "object_marking", "に": "location_vs_target", "へ": "direction"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "おかげ", "is_correct": true, "explanation": "「所為」が悪い結果の原因を言うのに対し、「おかげ」は良い結果の原因を言う対義語。"}, {"text": "責任", "is_correct": false, "explanation": "負うべきものを表し、良し悪しの原因の対ではない。"}, {"text": "事情", "is_correct": false, "explanation": "状況や理由を表し、対義語ではない。"}, {"text": "わけ", "is_correct": false, "explanation": "理由一般を表し、対義語ではない。"}], "correct_answer": "おかげ", "explanations": {"おかげ": "「所為」が悪い結果の原因を言うのに対し、「おかげ」は良い結果の原因を言う対義語。", "責任": "負うべきものを表し、良し悪しの原因の対ではない。", "事情": "状況や理由を表し、対義語ではない。", "わけ": "理由一般を表し、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a8a4674-0300-4d93-a215-8560fdf47e2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35904, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "表わす", "is_correct": true, "explanation": "正解：「あらわす」と読む対象語。"}, {"text": "笑わす", "is_correct": false, "explanation": "「わらわす」と読み、第一モーラ「あ」が「わ」に替わる一モーラ差。"}, {"text": "露わに", "is_correct": false, "explanation": "「あらわに」と読み、最後のモーラ「す」が「に」に替わる一モーラ差。"}, {"text": "現れ", "is_correct": false, "explanation": "「あらわれ」と読み、最後のモーラ「す」が「れ」に替わる一モーラ差。"}], "explanations": {"表わす": "正解：「あらわす」と読む対象語。", "笑わす": "「わらわす」と読み、第一モーラ「あ」が「わ」に替わる一モーラ差。", "露わに": "「あらわに」と読み、最後のモーラ「す」が「に」に替わる一モーラ差。", "現れ": "「あらわれ」と読み、最後のモーラ「す」が「れ」に替わる一モーラ差。"}, "sentence_index": null, "correct_answer": "表わす"}, "level_3": {"options": [{"text": "表わす", "is_correct": true, "explanation": "気持ちを言葉で外に示すことを表す。"}, {"text": "洗う", "is_correct": false, "explanation": "意味：気持ちを洗うことはできない。"}, {"text": "切る", "is_correct": false, "explanation": "連語：「言葉で切る」は不自然。"}, {"text": "運ぶ", "is_correct": false, "explanation": "意味：気持ちを言葉で運ぶとは言わない。"}], "explanations": {"表わす": "気持ちを言葉で外に示すことを表す。", "洗う": "意味：気持ちを洗うことはできない。", "切る": "連語：「言葉で切る」は不自然。", "運ぶ": "意味：気持ちを言葉で運ぶとは言わない。"}, "sentence_index": 0, "correct_answer": "表わす"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この絵は春が表わしている。", "explanation": "助詞の混同：表わす対象は「を」で示す。"}, {"text": "明日、この絵は春を表わした。", "explanation": "時制の誤り：「明日」と過去形が合わない。"}, {"text": "この一匹の絵は春を表わしている。", "explanation": "助数詞の誤り：絵を「匹」で数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a8a4674-0300-4d93-a215-8560fdf47e2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35904, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は喜びが顔に表わした。", "corrected_sentence": "彼は喜びを顔に表わした。", "error_description": "助詞の混同：表わす対象は「が」でなく「を」で示す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "表わした", "is_correct": true, "explanation": "過去の行為をた形で言い切る。"}, {"text": "表わして", "is_correct": false, "explanation": "て形では文が終わらない。"}, {"text": "表わせば", "is_correct": false, "explanation": "条件形で後件がなく文が成立しない。"}, {"text": "表わさ", "is_correct": false, "explanation": "未然形だけでは文にならない。"}], "correct_form": "表わした", "base_form": "表わす", "form_label": "た形（過去）", "sentence_index": 1, "explanations": {"表わした": "過去の行為をた形で言い切る。", "表わして": "て形では文が終わらない。", "表わせば": "条件形で後件がなく文が成立しない。", "表わさ": "未然形だけでは文にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a8a4674-0300-4d93-a215-8560fdf47e2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35904, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「表わす」の目的語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「気持ちに」では表わす対象にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は目的語を示せない。"}, {"text": "が", "is_correct": false, "explanation": "「気持ちが表わした」は他動詞と合わない。"}], "correct_answer": "を", "explanations": {"を": "「表わす」の目的語を示す。", "に": "「気持ちに」では表わす対象にならない。", "へ": "方向の「へ」は目的語を示せない。", "が": "「気持ちが表わした」は他動詞と合わない。"}, "error_tags": {"に": "location_vs_target", "へ": "direction", "が": "object_marking"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隠す", "is_correct": true, "explanation": "気持ちを外に示す「表わす」に対し、見せないようにする対義語。"}, {"text": "伝える", "is_correct": false, "explanation": "外に示す方向の語で対義語ではない。"}, {"text": "描く", "is_correct": false, "explanation": "表現の一種で対の関係ではない。"}, {"text": "話す", "is_correct": false, "explanation": "示す行為の一つで対義語ではない。"}], "correct_answer": "隠す", "explanations": {"隠す": "気持ちを外に示す「表わす」に対し、見せないようにする対義語。", "伝える": "外に示す方向の語で対義語ではない。", "描く": "表現の一種で対の関係ではない。", "話す": "示す行為の一つで対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a8a4674-0300-4d93-a215-8560fdf47e2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
