INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35910, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "するのがたいへんで、簡単にはできない。", "primary_collocate": null, "pronunciation": "むずかしい", "ipa": "mɯzɯkaɕiː", "syllable_count": 5, "sentences": [{"text": "この問題はとても難しい。", "target_word": "難しい", "complexity_tier": "T3", "furigana": "もんだい むずか", "sentence_source": "generated"}, {"text": "昨日のテストは難しかった。", "target_word": "難しかった", "complexity_tier": "T3", "furigana": "きのう むずか", "sentence_source": "generated"}, {"text": "難しい本を毎日少しずつ読んでいる。", "target_word": "難しい", "complexity_tier": "T3", "furigana": "むずか ほん まいにち すこ よ", "sentence_source": "generated"}, {"text": "数学は難しくて、よく分からない。", "target_word": "難しくて", "complexity_tier": "T3", "furigana": "すうがく むずか わ", "sentence_source": "generated"}, {"text": "この漢字は思ったより難しくない。", "target_word": "難しくない", "complexity_tier": "T3", "furigana": "かんじ おも むずか", "sentence_source": "generated"}, {"text": "早く起きるのは私には難しい。", "target_word": "難しい", "complexity_tier": "T3", "furigana": "はや お わたし むずか", "sentence_source": "generated"}, {"text": "先生は難しい言葉を使わない。", "target_word": "難しい", "complexity_tier": "T3", "furigana": "せんせい むずか ことば つか", "sentence_source": "generated"}, {"text": "料理は簡単そうで難しい。", "target_word": "難しい", "complexity_tier": "T3", "furigana": "りょうり かんたん むずか", "sentence_source": "generated"}, {"text": "難しい仕事を一人で終わらせた。", "target_word": "難しい", "complexity_tier": "T3", "furigana": "むずか しごと ひとり お", "sentence_source": "generated"}, {"text": "英語で話すのは難しかったけど楽しかった。", "target_word": "難しかった", "complexity_tier": "T3", "furigana": "えいご はな むずか たの", "sentence_source": "generated"}], "morphological_forms": [{"form": "難しかった", "label": "活用"}, {"form": "難しくて", "label": "活用"}, {"form": "難しくない", "label": "活用"}, {"form": "難しさ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形容詞 | するのが大変で簡単にできない", "collocate_groundin