INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35914, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "二つのものを並べて、どちらがどうかを見る。", "primary_collocate": null, "pronunciation": "くらべる", "ipa": "kɯɾabeɾɯ", "syllable_count": 4, "sentences": [{"text": "兄と背の高さを比べた。", "target_word": "比べた", "complexity_tier": "T3", "furigana": "あに せ たか くら", "sentence_source": "generated"}, {"text": "二つのかばんを比べて、安いほうを買った。", "target_word": "比べて", "complexity_tier": "T3", "furigana": "ふた くら やす か", "sentence_source": "generated"}, {"text": "去年と比べると、今年は暑い。", "target_word": "比べる", "complexity_tier": "T3", "furigana": "きょねん くら ことし あつ", "sentence_source": "generated"}, {"text": "友だちと自分を比べないでください。", "target_word": "比べない", "complexity_tier": "T3", "furigana": "とも じぶん くら", "sentence_source": "generated"}, {"text": "姉と私の手の大きさを比べてみた。", "target_word": "比べて", "complexity_tier": "T3", "furigana": "あね わたし て おお くら", "sentence_source": "generated"}, {"text": "どちらが速いか比べよう。", "target_word": "比べよう", "complexity_tier": "T3", "furigana": "はや くら", "sentence_source": "generated"}, {"text": "二人の絵を比べるのは難しい。", "target_word": "比べる", "complexity_tier": "T3", "furigana": "ふたり え くら むずか", "sentence_source": "generated"}, {"text": "昔の写真と比べて、町が変わった。", "target_word": "比べて", "complexity_tier": "T3", "furigana": "むかし しゃしん くら まち か", "sentence_source": "generated"}, {"text": "値段を比べてから決めます。", "target_word": "比べて", "complexity_tier": "T3", "furigana": "ねだん くら き", "sentence_source": "generated"}, {"text": "妹は二つのケーキを比べていた。", "target_word": "比べて", "complexity_tier": "T3", "furigana": "いもうと ふた くら", "sentence_source": "generated"}], "morphological_forms": [{"form": "比べた", "label": "活用"}, {"form": "比べて", "label": "活用"}, {"form": "比べない", "label": "活用"}, {"form": "比べられる", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 二つのものを並べて違いを見る", "collocate_grounding": {"status": "no_so