INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35915, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "二つ以上のものを同じ基準で見て、違いや同じところを調べる。", "primary_collocate": null, "pronunciation": "くらべる", "ipa": "kɯɾabeɾɯ", "syllable_count": 4, "sentences": [{"text": "三つの国の文化を比べて発表した。", "target_word": "比べて", "complexity_tier": "T3", "furigana": "みっ くに ぶんか くら はっぴょう", "sentence_source": "generated"}, {"text": "データを比べると、違いが分かる。", "target_word": "比べる", "complexity_tier": "T3", "furigana": "くら ちが わ", "sentence_source": "generated"}, {"text": "二つの意見を比べて考えた。", "target_word": "比べて", "complexity_tier": "T3", "furigana": "ふた いけん くら かんが", "sentence_source": "generated"}, {"text": "昔と今の生活を比べてみよう。", "target_word": "比べて", "complexity_tier": "T3", "furigana": "むかし いま せいかつ くら", "sentence_source": "generated"}, {"text": "実験の結果を比べた。", "target_word": "比べた", "complexity_tier": "T3", "furigana": "じっけん けっか くら", "sentence_source": "generated"}, {"text": "店ごとの値段を比べるのは大切だ。", "target_word": "比べる", "complexity_tier": "T3", "furigana": "みせ ねだん くら たいせつ", "sentence_source": "generated"}, {"text": "二つの文を比べて、同じ点を探した。", "target_word": "比べて", "complexity_tier": "T3", "furigana": "ふた ぶん くら おな てん さが", "sentence_source": "generated"}, {"text": "他の人と比べられるのは嫌だ。", "target_word": "比べられる", "complexity_tier": "T3", "furigana": "ほか ひと くら いや", "sentence_source": "generated"}, {"text": "先生はクラスの成績を比べていた。", "target_word": "比べて", "complexity_tier": "T3", "furigana": "せんせい せいせき くら", "sentence_source": "generated"}, {"text": "日本と外国の学校を比べた本を読んだ。", "target_word": "比べた", "complexity_tier": "T3", "furigana": "にほん がいこく がっこう くら ほん よ", "sentence_source": "generated"}], "morphological_forms": [{"form": "比べた", "label": "活用"}, {"form": "比べて", "label": "活用"}, {"form": "比べない", "label": "活用"}, {"form": "比べられる", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 同じ基準で違いや共通点を調べる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '319f2724-4ee5-4a6b-9aab-845914e32788') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35916, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "形や量などが、ふつうよりも多くの場所をとる。", "primary_collocate": null, "pronunciation": "おおきい", "ipa": "oːkiː", "syllable_count": 4, "sentences": [{"text": "この犬はとても大きい。", "target_word": "大きい", "complexity_tier": "T3", "furigana": "いぬ おお", "sentence_source": "generated"}, {"text": "大きい箱に本を入れた。", "target_word": "大きい", "complexity_tier": "T3", "furigana": "おお はこ ほん い", "sentence_source": "generated"}, {"text": "その魚は思ったより大きかった。", "target_word": "大きかった", "complexity_tier": "T3", "furigana": "さかな おも おお", "sentence_source": "generated"}, {"text": "彼の家は大きくて、庭も広い。", "target_word": "大きくて", "complexity_tier": "T3", "furigana": "かれ いえ おお にわ ひろ", "sentence_source": "generated"}, {"text": "この靴は私には大きい。", "target_word": "大きい", "complexity_tier": "T3", "furigana": "くつ わたし おお", "sentence_source": "generated"}, {"text": "私の部屋はあまり大きくない。", "target_word": "大きくない", "complexity_tier": "T3", "furigana": "わたし へや おお", "sentence_source": "generated"}, {"text": "大きい木の下で休んでいる。", "target_word": "大きい", "complexity_tier": "T3", "furigana": "おお き した やす", "sentence_source": "generated"}, {"text": "弟は大きいケーキを食べたがった。", "target_word": "大きい", "complexity_tier": "T3", "furigana": "おとうと おお た", "sentence_source": "generated"}, {"text": "駅の前に大きいビルができた。", "target_word": "大きい", "complexity_tier": "T3", "furigana": "えき まえ おお", "sentence_source": "generated"}, {"text": "子どものころ、父の手は大きかった。", "target_word": "大きかった", "complexity_tier": "T3", "furigana": "こ ちち て おお", "sentence_source": "generated"}], "morphological_forms": [{"form": "大きかった", "label": "活用"}, {"form": "大きくて", "label": "活用"}, {"form": "大きくない", "label": "活用"}, {"form": "大きさ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形容詞 | 形や量がふつうより大きい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '319f2724-4ee5-4a6b-9aab-845914e32788') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35905, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "表わす", "is_correct": true, "explanation": "正解：あらわす。気持ちを示すという意味。"}, {"text": "習わす", "is_correct": false, "explanation": "ならわす：最初の「あ」が「な」に変わった一モーラ差。習わせる、という意味。"}, {"text": "笑わす", "is_correct": false, "explanation": "わらわす：最初の「あ」が「わ」に変わった一モーラ差。人を笑わせる、という意味。"}, {"text": "荒らす", "is_correct": false, "explanation": "あらす：「わ」が一つ少ない語。場所をめちゃくちゃにする、という意味。"}], "explanations": {"表わす": "正解：あらわす。気持ちを示すという意味。", "習わす": "ならわす：最初の「あ」が「な」に変わった一モーラ差。習わせる、という意味。", "笑わす": "わらわす：最初の「あ」が「わ」に変わった一モーラ差。人を笑わせる、という意味。", "荒らす": "あらす：「わ」が一つ少ない語。場所をめちゃくちゃにする、という意味。"}, "sentence_index": null, "correct_answer": "表わす"}, "level_3": {"options": [{"text": "表わした", "is_correct": true, "explanation": "喜びの気持ちを顔に示した、という意味で自然。"}, {"text": "売った", "is_correct": false, "explanation": "意味：喜びは売るものではない。"}, {"text": "閉めた", "is_correct": false, "explanation": "連語：「喜びを閉める」とは言わない。"}, {"text": "忘れた", "is_correct": false, "explanation": "項構造：「顔に忘れた」は格の取り方が不自然。"}], "explanations": {"表わした": "喜びの気持ちを顔に示した、という意味で自然。", "売った": "意味：喜びは売るものではない。", "閉めた": "連語：「喜びを閉める」とは言わない。", "忘れた": "項構造：「顔に忘れた」は格の取り方が不自然。"}, "sentence_index": 0, "correct_answer": "表わした"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "感謝の気持ちが手紙を表わした。", "explanation": "助詞の混同：主語と目的語が逆になっている。「気持ちを手紙で表わした」が正しい。"}, {"text": "明日、感謝の気持ちを手紙で表わした。", "explanation": "活用・アスペクトの誤り：「明日」と過去形「た」が合わない。"}, {"text": "手紙で感謝の表わした気持ちを。", "explanation": "語順の誤り：文の形がこわれている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd665cdcb-c0c8-4ef7-8fc6-b3d6875088f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35905, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は喜びが顔に表わした。", "corrected_sentence": "彼は喜びを顔に表わした。", "error_description": "助詞の混同：「表わす」の目的語には「を」を使う。「喜びが」ではなく「喜びを」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "表わす", "is_correct": true, "explanation": "「のは」の前なので辞書形が正しい。"}, {"text": "表わした", "is_correct": false, "explanation": "過去形。「〜のは難しい」という一般的な話には合わない。"}, {"text": "表わして", "is_correct": false, "explanation": "て形。「のは」の前には入らない。"}, {"text": "表わそう", "is_correct": false, "explanation": "意向形。「のは」の前には入らない。"}], "correct_form": "表わす", "base_form": "表わす", "form_label": "活用", "sentence_index": 1, "explanations": {"表わす": "「のは」の前なので辞書形が正しい。", "表わした": "過去形。「〜のは難しい」という一般的な話には合わない。", "表わして": "て形。「のは」の前には入らない。", "表わそう": "意向形。「のは」の前には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd665cdcb-c0c8-4ef7-8fc6-b3d6875088f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35905, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "手段を表す「で」。言葉を使って示す。"}, {"text": "を", "is_correct": false, "explanation": "「気持ちを」と「を」が二つになり非文。"}, {"text": "が", "is_correct": false, "explanation": "「言葉が表わす」では主語になり、文の意味が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は手段を表せない。"}], "correct_answer": "で", "explanations": {"で": "手段を表す「で」。言葉を使って示す。", "を": "「気持ちを」と「を」が二つになり非文。", "が": "「言葉が表わす」では主語になり、文の意味が合わない。", "へ": "方向の「へ」は手段を表せない。"}, "error_tags": {"を": "object_marking", "が": "topic_vs_subject", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隠す", "is_correct": true, "explanation": "気持ちを見せないようにすること。「表わす」の反対。"}, {"text": "示す", "is_correct": false, "explanation": "似た意味の語で、反対ではない。"}, {"text": "書く", "is_correct": false, "explanation": "関係のない動作で、反対の意味ではない。"}, {"text": "選ぶ", "is_correct": false, "explanation": "意味が異なり、反対語ではない。"}], "correct_answer": "隠す", "explanations": {"隠す": "気持ちを見せないようにすること。「表わす」の反対。", "示す": "似た意味の語で、反対ではない。", "書く": "関係のない動作で、反対の意味ではない。", "選ぶ": "意味が異なり、反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd665cdcb-c0c8-4ef7-8fc6-b3d6875088f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35905, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "表わす", "is_correct": true, "explanation": "正解：あらわす（表わす）。"}, {"text": "合わす", "is_correct": false, "explanation": "あわす：「ら」が抜けた近い音の語。合わせる。"}, {"text": "交わす", "is_correct": false, "explanation": "かわす：「あら」が「か」になった近い音の語。"}, {"text": "洗う", "is_correct": false, "explanation": "あらう：語末が「わす」でなく「う」。"}], "explanations": {"表わす": "正解：あらわす（表わす）。", "合わす": "あわす：「ら」が抜けた近い音の語。合わせる。", "交わす": "かわす：「あら」が「か」になった近い音の語。", "洗う": "あらう：語末が「わす」でなく「う」。"}, "sentence_index": null, "correct_answer": "表わす"}, "level_3": {"options": [{"text": "表わして", "is_correct": true, "explanation": "記号が意味を示している、という文で自然。"}, {"text": "食べて", "is_correct": false, "explanation": "意味：記号は何かを食べない。"}, {"text": "寝て", "is_correct": false, "explanation": "項構造：「寝る」は「を」を取らない。"}, {"text": "泣いて", "is_correct": false, "explanation": "意味・項構造：記号は泣かず、「何を泣いて」も不自然。"}], "explanations": {"表わして": "記号が意味を示している、という文で自然。", "食べて": "意味：記号は何かを食べない。", "寝て": "項構造：「寝る」は「を」を取らない。", "泣いて": "意味・項構造：記号は泣かず、「何を泣いて」も不自然。"}, "sentence_index": 6, "correct_answer": "表わして"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は態度に反対の意見が表わした。", "explanation": "助詞の混同：「意見が」ではなく「意見を」。"}, {"text": "彼は態度で反対の意見を表わしてある。", "explanation": "アスペクトの誤り：「〜てある」はこの文では不自然。「表わした」が正しい。"}, {"text": "反対の彼は意見を態度で表わした。", "explanation": "語順の誤り：「反対の」が「彼」にかかってしまう。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd665cdcb-c0c8-4ef7-8fc6-b3d6875088f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35905, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "考えをうまく表わせない人になりたい。", "corrected_sentence": "考えをうまく表わせる人になりたい。", "error_description": "活用の誤り：「なりたい」と合うのは肯定の可能形「表わせる」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "表わせる", "is_correct": true, "explanation": "可能形。「うまくできる」という意味になる。"}, {"text": "表わして", "is_correct": false, "explanation": "て形。名詞「人」を直接修飾できない。"}, {"text": "表わした", "is_correct": false, "explanation": "過去形。これからなりたい人の説明に合わない。"}, {"text": "表わされる", "is_correct": false, "explanation": "受身形。考えを自分で示す意味にならない。"}], "correct_form": "表わせる", "base_form": "表わす", "form_label": "活用", "sentence_index": 7, "explanations": {"表わせる": "可能形。「うまくできる」という意味になる。", "表わして": "て形。名詞「人」を直接修飾できない。", "表わした": "過去形。これからなりたい人の説明に合わない。", "表わされる": "受身形。考えを自分で示す意味にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd665cdcb-c0c8-4ef7-8fc6-b3d6875088f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35905, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "可能動詞の目的語を表す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「考えに表わせる」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "「考えで表わせる」では何を示すのか分からない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は目的語を表せない。"}], "correct_answer": "を", "explanations": {"を": "可能動詞の目的語を表す「を」。", "に": "「考えに表わせる」は不自然。", "で": "「考えで表わせる」では何を示すのか分からない。", "へ": "方向の「へ」は目的語を表せない。"}, "error_tags": {"に": "location_vs_target", "で": "instrument", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隠す", "is_correct": true, "explanation": "見えないようにする。「表わす」の反対。"}, {"text": "伝える", "is_correct": false, "explanation": "似た意味で、反対ではない。"}, {"text": "走る", "is_correct": false, "explanation": "関係のない動作。"}, {"text": "待つ", "is_correct": false, "explanation": "意味が異なり、反対語ではない。"}], "correct_answer": "隠す", "explanations": {"隠す": "見えないようにする。「表わす」の反対。", "伝える": "似た意味で、反対ではない。", "走る": "関係のない動作。", "待つ": "意味が異なり、反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd665cdcb-c0c8-4ef7-8fc6-b3d6875088f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35910, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "難しい", "is_correct": true, "explanation": "正解：むずかしい。"}, {"text": "恥ずかしい", "is_correct": false, "explanation": "はずかしい：最初の「む」が「は」に変わった一モーラ差。"}, {"text": "むず痒い", "is_correct": false, "explanation": "むずがゆい：「か」が「が」、「し」が「ゆ」になった近い音の語。"}, {"text": "珍しい", "is_correct": false, "explanation": "めずらしい：「む」が「め」、「か」が「ら」になった近い音の語。"}], "explanations": {"難しい": "正解：むずかしい。", "恥ずかしい": "はずかしい：最初の「む」が「は」に変わった一モーラ差。", "むず痒い": "むずがゆい：「か」が「が」、「し」が「ゆ」になった近い音の語。", "珍しい": "めずらしい：「む」が「め」、「か」が「ら」になった近い音の語。"}, "sentence_index": null, "correct_answer": "難しい"}, "level_3": {"options": [{"text": "難しい", "is_correct": true, "explanation": "問題が簡単に解けない、という意味で自然。"}, {"text": "寒い", "is_correct": false, "explanation": "意味：問題に温度はない。"}, {"text": "青い", "is_correct": false, "explanation": "意味：問題に色はない。"}, {"text": "甘い", "is_correct": false, "explanation": "意味：問題に味はない。"}], "explanations": {"難しい": "問題が簡単に解けない、という意味で自然。", "寒い": "意味：問題に温度はない。", "青い": "意味：問題に色はない。", "甘い": "意味：問題に味はない。"}, "sentence_index": 0, "correct_answer": "難しい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "数学を難しくて、よく分からない。", "explanation": "助詞の混同：「数学を」ではなく「数学は」。"}, {"text": "数学は難しいくて、よく分からない。", "explanation": "活用の誤り：い形容詞のて形は「難しくて」。"}, {"text": "よく数学は分からない難しくて。", "explanation": "語順の誤り：文の形がこわれている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd665cdcb-c0c8-4ef7-8fc6-b3d6875088f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35910, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日のテストは難しいだった。", "corrected_sentence": "昨日のテストは難しかった。", "error_description": "活用の誤り：い形容詞の過去形は「難しかった」。「難しいだった」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "難しかった", "is_correct": true, "explanation": "「昨日」なので過去形が正しい。"}, {"text": "難しい", "is_correct": false, "explanation": "現在形。「昨日」と合わない。"}, {"text": "難しくて", "is_correct": false, "explanation": "て形。文がここで終わらない。"}, {"text": "難しくない", "is_correct": false, "explanation": "否定形。過去の話にならない。"}], "correct_form": "難しかった", "base_form": "難しい", "form_label": "活用", "sentence_index": 1, "explanations": {"難しかった": "「昨日」なので過去形が正しい。", "難しい": "現在形。「昨日」と合わない。", "難しくて": "て形。文がここで終わらない。", "難しくない": "否定形。過去の話にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd665cdcb-c0c8-4ef7-8fc6-b3d6875088f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35910, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "易しい", "is_correct": true, "explanation": "簡単にできること。「難しい」の反対。"}, {"text": "新しい", "is_correct": false, "explanation": "関係のない性質。"}, {"text": "遠い", "is_correct": false, "explanation": "距離の語で、反対語ではない。"}, {"text": "広い", "is_correct": false, "explanation": "広さの語で、反対語ではない。"}], "correct_answer": "易しい", "explanations": {"易しい": "簡単にできること。「難しい」の反対。", "新しい": "関係のない性質。", "遠い": "距離の語で、反対語ではない。", "広い": "広さの語で、反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd665cdcb-c0c8-4ef7-8fc6-b3d6875088f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35910, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "難しい", "is_correct": true, "explanation": "正解：むずかしい（難しい）。"}, {"text": "悔しい", "is_correct": false, "explanation": "くやしい：語末「しい」が同じ近い音の語。"}, {"text": "懐かしい", "is_correct": false, "explanation": "なつかしい：「かしい」が同じ近い音の語。"}, {"text": "忙しい", "is_correct": false, "explanation": "いそがしい：「しい」で終わる近い音の語。"}], "explanations": {"難しい": "正解：むずかしい（難しい）。", "悔しい": "くやしい：語末「しい」が同じ近い音の語。", "懐かしい": "なつかしい：「かしい」が同じ近い音の語。", "忙しい": "いそがしい：「しい」で終わる近い音の語。"}, "sentence_index": null, "correct_answer": "難しい"}, "level_3": {"options": [{"text": "難しい", "is_correct": true, "explanation": "分かりにくい言葉、という意味で自然。"}, {"text": "丸い", "is_correct": false, "explanation": "意味：言葉に形はない。"}, {"text": "四角い", "is_correct": false, "explanation": "意味：言葉は四角くない。"}, {"text": "赤い", "is_correct": false, "explanation": "意味：言葉に色はない。"}], "explanations": {"難しい": "分かりにくい言葉、という意味で自然。", "丸い": "意味：言葉に形はない。", "四角い": "意味：言葉は四角くない。", "赤い": "意味：言葉に色はない。"}, "sentence_index": 6, "correct_answer": "難しい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "英語を話すのが難しかったを楽しかった。", "explanation": "助詞の混同：「けど」の代わりに「を」は使えない。"}, {"text": "英語で話すのは難しいかったけど楽しかった。", "explanation": "活用の誤り：過去形は「難しかった」。"}, {"text": "英語で難しかった話すのはけど楽しかった。", "explanation": "語順の誤り：文の形がこわれている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd665cdcb-c0c8-4ef7-8fc6-b3d6875088f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35910, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "料理は簡単そうで難しいだ。", "corrected_sentence": "料理は簡単そうで難しい。", "error_description": "活用の誤り：い形容詞の後に「だ」はつけない。「難しい。」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "難しい", "is_correct": true, "explanation": "文の終わりで、今のことなので現在形。"}, {"text": "難しく", "is_correct": false, "explanation": "連用形。文がここで終われない。"}, {"text": "難しくて", "is_correct": false, "explanation": "て形。文が終わらない。"}, {"text": "難しさ", "is_correct": false, "explanation": "名詞形。文末に「難しさ。」だけでは文にならない。"}], "correct_form": "難しい", "base_form": "難しい", "form_label": "活用", "sentence_index": 7, "explanations": {"難しい": "文の終わりで、今のことなので現在形。", "難しく": "連用形。文がここで終われない。", "難しくて": "て形。文が終わらない。", "難しさ": "名詞形。文末に「難しさ。」だけでは文にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd665cdcb-c0c8-4ef7-8fc6-b3d6875088f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
