INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35914, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "比べる", "is_correct": true, "explanation": "正解：くらべる。"}, {"text": "調べる", "is_correct": false, "explanation": "しらべる：最初の「く」が「し」に変わった一モーラ差。"}, {"text": "並べる", "is_correct": false, "explanation": "ならべる：最初の「く」が「な」に変わった一モーラ差。"}, {"text": "暮らせる", "is_correct": false, "explanation": "くらせる：「べ」が「せ」に変わった一モーラ差。暮らすことができる。"}], "explanations": {"比べる": "正解：くらべる。", "調べる": "しらべる：最初の「く」が「し」に変わった一モーラ差。", "並べる": "ならべる：最初の「く」が「な」に変わった一モーラ差。", "暮らせる": "くらせる：「べ」が「せ」に変わった一モーラ差。暮らすことができる。"}, "sentence_index": null, "correct_answer": "比べる"}, "level_3": {"options": [{"text": "比べた", "is_correct": true, "explanation": "兄と高さを比べた、で自然。"}, {"text": "食べた", "is_correct": false, "explanation": "意味：高さは食べられない。"}, {"text": "洗った", "is_correct": false, "explanation": "意味：高さは洗えない。"}, {"text": "開けた", "is_correct": false, "explanation": "連語：「高さを開ける」とは言わない。"}], "explanations": {"比べた": "兄と高さを比べた、で自然。", "食べた": "意味：高さは食べられない。", "洗った": "意味：高さは洗えない。", "開けた": "連語：「高さを開ける」とは言わない。"}, "sentence_index": 0, "correct_answer": "比べた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友だちが自分を比べないでください。", "explanation": "助詞の混同：「友だちと」が正しい。"}, {"text": "友だちと自分を比べなかったでください。", "explanation": "活用の誤り：「〜ないでください」の形が正しい。"}, {"text": "自分をください友だちと比べないで。", "explanation": "語順の誤り：文の形がこわれている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd665cdcb-c0c8-4ef7-8fc6-b3d6875088f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35914, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄で背の高さを比べた。", "corrected_sentence": "兄と背の高さを比べた。", "error_description": "助詞の混同：比べる相手には「と」を使う。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "比べて", "is_correct": true, "explanation": "後ろに文が続くので、て形。"}, {"text": "比べる", "is_correct": false, "explanation": "辞書形。ここで読点が続くのは不自然。"}, {"text": "比べない", "is_correct": false, "explanation": "否定形。比べずに買ったことになり、意味が合わない。"}, {"text": "比べられる", "is_correct": false, "explanation": "受身・可能形。自分で比べた意味にならない。"}], "correct_form": "比べて", "base_form": "比べる", "form_label": "活用", "sentence_index": 1, "explanations": {"比べて": "後ろに文が続くので、て形。", "比べる": "辞書形。ここで読点が続くのは不自然。", "比べない": "否定形。比べずに買ったことになり、意味が合わない。", "比べられる": "受身・可能形。自分で比べた意味にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd665cdcb-c0c8-4ef7-8fc6-b3d6875088f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
