INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35914, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "比べる", "is_correct": true, "explanation": "正解：くらべる（比べる）。"}, {"text": "食べる", "is_correct": false, "explanation": "たべる：「くら」が「た」になった近い音の語。"}, {"text": "滑る", "is_correct": false, "explanation": "すべる：「べる」が同じ近い音の語。"}, {"text": "暮れる", "is_correct": false, "explanation": "くれる：「く」で始まる近い音の語。"}], "explanations": {"比べる": "正解：くらべる（比べる）。", "食べる": "たべる：「くら」が「た」になった近い音の語。", "滑る": "すべる：「べる」が同じ近い音の語。", "暮れる": "くれる：「く」で始まる近い音の語。"}, "sentence_index": null, "correct_answer": "比べる"}, "level_3": {"options": [{"text": "比べる", "is_correct": true, "explanation": "二人の絵を見て違いを考える、で自然。"}, {"text": "飲む", "is_correct": false, "explanation": "意味：絵は飲めない。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "項構造：「泳ぐ」は「絵を」を取らない。"}, {"text": "寝る", "is_correct": false, "explanation": "項構造：「寝る」は目的語を取らない。"}], "explanations": {"比べる": "二人の絵を見て違いを考える、で自然。", "飲む": "意味：絵は飲めない。", "泳ぐ": "項構造：「泳ぐ」は「絵を」を取らない。", "寝る": "項構造：「寝る」は目的語を取らない。"}, "sentence_index": 6, "correct_answer": "比べる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妹は二つのケーキが比べていた。", "explanation": "助詞の混同：「ケーキを」が正しい。"}, {"text": "妹は二つのケーキを比べるいた。", "explanation": "活用の誤り：「比べていた」が正しい。"}, {"text": "妹は比べていた二つのをケーキ。", "explanation": "語順の誤り：文の形がこわれている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd665cdcb-c0c8-4ef7-8fc6-b3d6875088f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
