INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35918, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ほかの場所から、話し手のいる所へ近づいて着くこと。", "primary_collocate": null, "pronunciation": "くる", "ipa": "kɯɾɯ", "syllable_count": 2, "sentences": [{"text": "友だちが明日うちに来る。", "target_word": "来る", "complexity_tier": "T3", "furigana": "ともだち あした く", "sentence_source": "generated"}, {"text": "バスがもうすぐ来る。", "target_word": "来る", "complexity_tier": "T3", "furigana": "く", "sentence_source": "generated"}, {"text": "先生が教室に来た。", "target_word": "来", "complexity_tier": "T3", "furigana": "せんせい きょうしつ き", "sentence_source": "generated"}, {"text": "犬がこっちに来ると、子どもが笑う。", "target_word": "来る", "complexity_tier": "T3", "furigana": "いぬ く こ わら", "sentence_source": "generated"}, {"text": "姉は駅まで車で来ている。", "target_word": "来", "complexity_tier": "T3", "furigana": "あね えき くるま き", "sentence_source": "generated"}, {"text": "早く来てくれてうれしかった。", "target_word": "来", "complexity_tier": "T3", "furigana": "はや き", "sentence_source": "generated"}, {"text": "彼は今日学校に来ない。", "target_word": "来", "complexity_tier": "T3", "furigana": "かれ きょう がっこう こ", "sentence_source": "generated"}, {"text": "来る人はみんな笑顔だった。", "target_word": "来る", "complexity_tier": "T3", "furigana": "く ひと えがお", "sentence_source": "generated"}, {"text": "祖母が毎年夏に来る。", "target_word": "来る", "complexity_tier": "T3", "furigana": "そぼ まいとし なつ く", "sentence_source": "generated"}, {"text": "一人でここまで来られる？", "target_word": "来", "complexity_tier": "T3", "furigana": "ひとり こ", "sentence_source": "generated"}], "morphological_forms": [{"form": "来た", "label": "活用"}, {"form": "来て", "label": "活用"}, {"form": "来ない", "label": "活用"}, {"form": "来られる", "label": "活用"}, {"form": "いらっしゃる", "label": "敬語形"}], "register": "plain", "sense_fingerprint": "動詞 | ほかの所から話し手の方へ移動する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15902d2d-55f5-4a34-8e23-b9d6a857e21a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35920, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "音楽や言葉を、しるしを使って書き表すこと。", "primary_collocate": null, "pronunciation": "きふ", "ipa": "kʲiɸɯ", "syllable_count": 2, "sentences": [{"text": "音楽の記譜を習い始めた。", "target_word": "記譜", "complexity_tier": "T3", "furigana": "おんがく きふ なら はじ", "sentence_source": "generated"}, {"text": "彼は記譜がとても早い。", "target_word": "記譜", "complexity_tier": "T3", "furigana": "かれ きふ はや", "sentence_source": "generated"}, {"text": "記譜には五線を使う。", "target_word": "記譜", "complexity_tier": "T3", "furigana": "きふ ごせん つか", "sentence_source": "generated"}, {"text": "昔の記譜は今と違った。", "target_word": "記譜", "complexity_tier": "T3", "furigana": "むかし きふ いま ちが", "sentence_source": "generated"}, {"text": "記譜のしかたを先生に聞いた。", "target_word": "記譜", "complexity_tier": "T3", "furigana": "きふ せんせい き", "sentence_source": "generated"}, {"text": "この曲の記譜は難しい。", "target_word": "記譜", "complexity_tier": "T3", "furigana": "きょく きふ むずか", "sentence_source": "generated"}, {"text": "記譜ができると作曲に役立つ。", "target_word": "記譜", "complexity_tier": "T3", "furigana": "きふ さっきょく やくだ", "sentence_source": "generated"}, {"text": "祖父は手で記譜している。", "target_word": "記譜", "complexity_tier": "T3", "furigana": "そふ て きふ", "sentence_source": "generated"}, {"text": "記譜の記号を覚えたい。", "target_word": "記譜", "complexity_tier": "T3", "furigana": "きふ きごう おぼ", "sentence_source": "generated"}, {"text": "記譜された楽しい歌を歌った。", "target_word": "記譜", "complexity_tier": "T3", "furigana": "きふ たの うた うた", "sentence_source": "generated"}], "morphological_forms": [{"form": "記譜する", "label": "派生"}, {"form": "記譜法", "label": "派生"}, {"form": "記譜された", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 音や言葉を記号で書き表すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-