INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35918, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "来る", "is_correct": true, "explanation": "正解。読みは「くる」。"}, {"text": "栗", "is_correct": false, "explanation": "「くり」と読み、二モーラ目が「る」→「り」の一モーラ差。"}, {"text": "靴", "is_correct": false, "explanation": "「くつ」と読み、二モーラ目が「る」→「つ」の一モーラ差。"}, {"text": "黒", "is_correct": false, "explanation": "「くろ」と読み、二モーラ目が「る」→「ろ」の一モーラ差。"}, {"text": "熊", "is_correct": false, "explanation": "「くま」と読み、二モーラ目が「る」→「ま」の一モーラ差。"}, {"text": "草", "is_correct": false, "explanation": "「くさ」と読み、二モーラ目が「る」→「さ」の一モーラ差。"}], "explanations": {"来る": "正解。読みは「くる」。", "栗": "「くり」と読み、二モーラ目が「る」→「り」の一モーラ差。", "靴": "「くつ」と読み、二モーラ目が「る」→「つ」の一モーラ差。", "黒": "「くろ」と読み、二モーラ目が「る」→「ろ」の一モーラ差。", "熊": "「くま」と読み、二モーラ目が「る」→「ま」の一モーラ差。", "草": "「くさ」と読み、二モーラ目が「る」→「さ」の一モーラ差。"}, "sentence_index": null, "correct_answer": "来る"}, "level_3": {"options": [{"text": "来る", "is_correct": true, "explanation": "ほかの所から話し手のいる「うち」へ移動するので自然。"}, {"text": "食べる", "is_correct": false, "explanation": "項構造：「うちに食べる」とは言えない。"}, {"text": "読む", "is_correct": false, "explanation": "項構造：「うちに読む」は着点の「に」と合わない。"}, {"text": "書く", "is_correct": false, "explanation": "意味：友だちが明日うちに書くは意味が通らない。"}], "explanations": {"来る": "ほかの所から話し手のいる「うち」へ移動するので自然。", "食べる": "項構造：「うちに食べる」とは言えない。", "読む": "項構造：「うちに読む」は着点の「に」と合わない。", "書く": "意味：友だちが明日うちに書くは意味が通らない。"}, "sentence_index": 0, "correct_answer": "来る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日、兄がうちに来る。", "explanation": "活用・アスペクトの誤り：「昨日」があるので「来た」が必要。"}, {"text": "先生で教室に来た。", "explanation": "助詞の混同：主語は「が」で示し、「で」は使えない。"}, {"text": "友だちを公園に来た。", "explanation": "助詞の混同：「来る」は自動詞なので「を」で主語を示せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c524568e-9434-4131-839a-fdec07acbb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35918, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友だちを明日うちに来る。", "corrected_sentence": "友だちが明日うちに来る。", "error_description": "助詞の混同：来る人は「を」ではなく「が」で示す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "来る", "is_correct": true, "explanation": "「もうすぐ」はこれからのことなので辞書形が合う。"}, {"text": "来た", "is_correct": false, "explanation": "「もうすぐ」と過去形は合わない。"}, {"text": "来て", "is_correct": false, "explanation": "て形では文が終わらない。"}, {"text": "来よう", "is_correct": false, "explanation": "意向形はバスの動きには使えない。"}], "correct_form": "来る", "base_form": "来る", "form_label": "辞書形", "sentence_index": 1, "explanations": {"来る": "「もうすぐ」はこれからのことなので辞書形が合う。", "来た": "「もうすぐ」と過去形は合わない。", "来て": "て形では文が終わらない。", "来よう": "意向形はバスの動きには使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c524568e-9434-4131-839a-fdec07acbb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35918, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「うち」は来る先（着点）なので「に」。"}, {"text": "を", "is_correct": false, "explanation": "「来る」は自動詞で「を」の目的語をとらない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は動作の場所で、着点を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「うちの来る」は文の形にならない。"}], "correct_answer": "に", "explanations": {"に": "「うち」は来る先（着点）なので「に」。", "を": "「来る」は自動詞で「を」の目的語をとらない。", "で": "「で」は動作の場所で、着点を示せない。", "の": "「うちの来る」は文の形にならない。"}, "error_tags": {"を": "object_marking", "で": "location_vs_target", "の": "other"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "行く", "is_correct": true, "explanation": "話し手の所へ近づく「来る」に対し、離れていく「行く」が対義語。"}, {"text": "走る", "is_correct": false, "explanation": "移動の様子で、方向の対立はない。"}, {"text": "歩く", "is_correct": false, "explanation": "移動の手段で、対義関係ではない。"}, {"text": "待つ", "is_correct": false, "explanation": "移動しないことで、方向の対義語ではない。"}], "correct_answer": "行く", "explanations": {"行く": "話し手の所へ近づく「来る」に対し、離れていく「行く」が対義語。", "走る": "移動の様子で、方向の対立はない。", "歩く": "移動の手段で、対義関係ではない。", "待つ": "移動しないことで、方向の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c524568e-9434-4131-839a-fdec07acbb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35918, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "来る", "is_correct": true, "explanation": "正解。読みは「くる」。"}, {"text": "首", "is_correct": false, "explanation": "「くび」と読み、二モーラ目が「る」→「び」の一モーラ差。"}, {"text": "雲", "is_correct": false, "explanation": "「くも」と読み、二モーラ目が「る」→「も」の一モーラ差。"}, {"text": "夜", "is_correct": false, "explanation": "「よる」と読み、一モーラ目が「く」→「よ」の一モーラ差。"}, {"text": "猿", "is_correct": false, "explanation": "「さる」と読み、一モーラ目が「く」→「さ」の一モーラ差。"}, {"text": "丸", "is_correct": false, "explanation": "「まる」と読み、一モーラ目が「く」→「ま」の一モーラ差。"}], "explanations": {"来る": "正解。読みは「くる」。", "首": "「くび」と読み、二モーラ目が「る」→「び」の一モーラ差。", "雲": "「くも」と読み、二モーラ目が「る」→「も」の一モーラ差。", "夜": "「よる」と読み、一モーラ目が「く」→「よ」の一モーラ差。", "猿": "「さる」と読み、一モーラ目が「く」→「さ」の一モーラ差。", "丸": "「まる」と読み、一モーラ目が「く」→「ま」の一モーラ差。"}, "sentence_index": null, "correct_answer": "来る"}, "level_3": {"options": [{"text": "来", "is_correct": true, "explanation": "「来ない」となり、学校に姿を見せないという意味で自然。"}, {"text": "食べ", "is_correct": false, "explanation": "項構造：「学校に食べない」は「に」と合わない。"}, {"text": "読ま", "is_correct": false, "explanation": "項構造：「学校に読まない」は意味が通らない。"}, {"text": "飲ま", "is_correct": false, "explanation": "意味：学校に飲まないでは文が成り立たない。"}], "explanations": {"来": "「来ない」となり、学校に姿を見せないという意味で自然。", "食べ": "項構造：「学校に食べない」は「に」と合わない。", "読ま": "項構造：「学校に読まない」は意味が通らない。", "飲ま": "意味：学校に飲まないでは文が成り立たない。"}, "sentence_index": 6, "correct_answer": "来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日、姉がここに来た。", "explanation": "活用・アスペクトの誤り：「明日」には「来る」が必要。"}, {"text": "祖母はバスを来た。", "explanation": "助詞の混同：手段は「で」。「バスで来た」が正しい。"}, {"text": "来るた人が多い。", "explanation": "活用の誤り：過去は「来た」で、「来るた」という形はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c524568e-9434-4131-839a-fdec07acbb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35918, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は昨日学校に来ない。", "corrected_sentence": "彼は昨日学校に来なかった。", "error_description": "活用・アスペクトの誤り：「昨日」なので過去否定「来なかった」にする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "来る", "is_correct": true, "explanation": "名詞「人」を修飾するので辞書形（連体形）が合う。"}, {"text": "来て", "is_correct": false, "explanation": "て形は名詞を直接修飾できない。"}, {"text": "来れば", "is_correct": false, "explanation": "条件形は名詞を修飾できない。"}, {"text": "来よう", "is_correct": false, "explanation": "意向形は名詞の前に置けない。"}], "correct_form": "来る", "base_form": "来る", "form_label": "辞書形", "sentence_index": 7, "explanations": {"来る": "名詞「人」を修飾するので辞書形（連体形）が合う。", "来て": "て形は名詞を直接修飾できない。", "来れば": "条件形は名詞を修飾できない。", "来よう": "意向形は名詞の前に置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c524568e-9434-4131-839a-fdec07acbb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35918, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「来る」人を主格の「が」で示す。"}, {"text": "を", "is_correct": false, "explanation": "「来る」は自動詞で、主語を「を」で示せない。"}, {"text": "で", "is_correct": false, "explanation": "「友だちで」は手段・場所となり主語にならない。"}, {"text": "に", "is_correct": false, "explanation": "「友だちに」では来る人が示せない。"}], "correct_answer": "が", "explanations": {"が": "「来る」人を主格の「が」で示す。", "を": "「来る」は自動詞で、主語を「を」で示せない。", "で": "「友だちで」は手段・場所となり主語にならない。", "に": "「友だちに」では来る人が示せない。"}, "error_tags": {"を": "object_marking", "で": "instrument", "に": "location_vs_target"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "行く", "is_correct": true, "explanation": "こちらへ近づく「来る」と、向こうへ離れる「行く」は対義語。"}, {"text": "見る", "is_correct": false, "explanation": "移動ではなく、方向の対立がない。"}, {"text": "乗る", "is_correct": false, "explanation": "乗り物に関わる動作で、対義ではない。"}, {"text": "止まる", "is_correct": false, "explanation": "動きをやめることで、方向の対義語ではない。"}], "correct_answer": "行く", "explanations": {"行く": "こちらへ近づく「来る」と、向こうへ離れる「行く」は対義語。", "見る": "移動ではなく、方向の対立がない。", "乗る": "乗り物に関わる動作で、対義ではない。", "止まる": "動きをやめることで、方向の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c524568e-9434-4131-839a-fdec07acbb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35920, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "記譜", "is_correct": true, "explanation": "正解。読みは「きふ」。"}, {"text": "皮膚", "is_correct": false, "explanation": "「ひふ」と読み、一モーラ目が「き」→「ひ」の一モーラ差。"}, {"text": "菊", "is_correct": false, "explanation": "「きく」と読み、二モーラ目が「ふ」→「く」の一モーラ差。"}, {"text": "傷", "is_correct": false, "explanation": "「きず」と読み、二モーラ目が「ふ」→「ず」の一モーラ差。"}, {"text": "北", "is_correct": false, "explanation": "「きた」と読み、二モーラ目が「ふ」→「た」の一モーラ差。"}, {"text": "絹", "is_correct": false, "explanation": "「きぬ」と読み、二モーラ目が「ふ」→「ぬ」の一モーラ差。"}], "explanations": {"記譜": "正解。読みは「きふ」。", "皮膚": "「ひふ」と読み、一モーラ目が「き」→「ひ」の一モーラ差。", "菊": "「きく」と読み、二モーラ目が「ふ」→「く」の一モーラ差。", "傷": "「きず」と読み、二モーラ目が「ふ」→「ず」の一モーラ差。", "北": "「きた」と読み、二モーラ目が「ふ」→「た」の一モーラ差。", "絹": "「きぬ」と読み、二モーラ目が「ふ」→「ぬ」の一モーラ差。"}, "sentence_index": null, "correct_answer": "記譜"}, "level_3": {"options": [{"text": "記譜", "is_correct": true, "explanation": "音楽を記号で書く方法なので「音楽の記譜を習う」は自然。"}, {"text": "天気", "is_correct": false, "explanation": "意味：天気は習うものではない。"}, {"text": "机", "is_correct": false, "explanation": "意味：机は習い始めるものではない。"}, {"text": "切手", "is_correct": false, "explanation": "連語：「音楽の切手を習う」という結びつきはない。"}], "explanations": {"記譜": "音楽を記号で書く方法なので「音楽の記譜を習う」は自然。", "天気": "意味：天気は習うものではない。", "机": "意味：机は習い始めるものではない。", "切手": "連語：「音楽の切手を習う」という結びつきはない。"}, "sentence_index": 0, "correct_answer": "記譜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "記譜を三本書いた。", "explanation": "助数詞の誤り：記譜は「本」で数えない。"}, {"text": "私は記譜に歌を聞いた。", "explanation": "助詞の混同：「記譜で」や「記譜を見て」とすべき。"}, {"text": "記譜を食べた。", "explanation": "意味の誤り：記譜は書き表すことで、食べるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c524568e-9434-4131-839a-fdec07acbb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
