INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35920, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "記譜", "is_correct": true, "explanation": "正解。読みは「きふ」。"}, {"text": "主婦", "is_correct": false, "explanation": "「しゅふ」と読み、一モーラ目が「き」→「しゅ」の一モーラ差。"}, {"text": "岸", "is_correct": false, "explanation": "「きし」と読み、二モーラ目が「ふ」→「し」の一モーラ差。"}, {"text": "霧", "is_correct": false, "explanation": "「きり」と読み、二モーラ目が「ふ」→「り」の一モーラ差。"}, {"text": "牙", "is_correct": false, "explanation": "「きば」と読み、二モーラ目が「ふ」→「ば」の一モーラ差。"}, {"text": "木戸", "is_correct": false, "explanation": "「きど」と読み、二モーラ目が「ふ」→「ど」の一モーラ差。"}], "explanations": {"記譜": "正解。読みは「きふ」。", "主婦": "「しゅふ」と読み、一モーラ目が「き」→「しゅ」の一モーラ差。", "岸": "「きし」と読み、二モーラ目が「ふ」→「し」の一モーラ差。", "霧": "「きり」と読み、二モーラ目が「ふ」→「り」の一モーラ差。", "牙": "「きば」と読み、二モーラ目が「ふ」→「ば」の一モーラ差。", "木戸": "「きど」と読み、二モーラ目が「ふ」→「ど」の一モーラ差。"}, "sentence_index": null, "correct_answer": "記譜"}, "level_3": {"options": [{"text": "記譜", "is_correct": true, "explanation": "音を記号で書けると曲作りに役立つので自然。"}, {"text": "昼寝", "is_correct": false, "explanation": "意味：昼寝は作曲の役に立つ能力ではない。"}, {"text": "洗濯", "is_correct": false, "explanation": "意味：洗濯ができても作曲とは関係がない。"}, {"text": "買い物", "is_correct": false, "explanation": "連語：「買い物ができると作曲に役立つ」は結びつかない。"}], "explanations": {"記譜": "音を記号で書けると曲作りに役立つので自然。", "昼寝": "意味：昼寝は作曲の役に立つ能力ではない。", "洗濯": "意味：洗濯ができても作曲とは関係がない。", "買い物": "連語：「買い物ができると作曲に役立つ」は結びつかない。"}, "sentence_index": 6, "correct_answer": "記譜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "記譜で二匹書いた。", "explanation": "助数詞の誤り：「匹」は動物を数える。"}, {"text": "彼は記譜を明日した。", "explanation": "語順・アスペクトの誤り：「明日」と過去「した」が合わない。"}, {"text": "記譜を飲んで元気になった。", "explanation": "意味の誤り：記譜は飲むものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c524568e-9434-4131-839a-fdec07acbb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, promp