INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35937, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "細く長く引いたすじ。", "primary_collocate": null, "pronunciation": "せん", "ipa": "seɴ", "syllable_count": 2, "sentences": [{"text": "紙に鉛筆で線を一本引いた。", "target_word": "線", "complexity_tier": "T3", "furigana": "かみ えんぴつ せん いっぽん ひ", "sentence_source": "generated"}, {"text": "白い線の内側で待ってください。", "target_word": "線", "complexity_tier": "T3", "furigana": "しろ せん うちがわ ま", "sentence_source": "generated"}, {"text": "線を消しゴムで消した。", "target_word": "線", "complexity_tier": "T3", "furigana": "せん け け", "sentence_source": "generated"}, {"text": "この線は少し曲がっている。", "target_word": "線", "complexity_tier": "T3", "furigana": "せん すこ ま", "sentence_source": "generated"}, {"text": "太い線で名前を書いた。", "target_word": "線", "complexity_tier": "T3", "furigana": "ふと せん なまえ か", "sentence_source": "generated"}, {"text": "道路に白い線がかいてある。", "target_word": "線", "complexity_tier": "T3", "furigana": "どうろ しろ せん", "sentence_source": "generated"}, {"text": "妹は線をなぞって字を練習する。", "target_word": "線", "complexity_tier": "T3", "furigana": "いもうと せん じ れんしゅう", "sentence_source": "generated"}, {"text": "グラフの線が上に向かっている。", "target_word": "線", "complexity_tier": "T3", "furigana": "せん うえ む", "sentence_source": "generated"}, {"text": "点と点を線でつないでみよう。", "target_word": "線", "complexity_tier": "T3", "furigana": "てん てん せん", "sentence_source": "generated"}, {"text": "この線より後ろに並んでね。", "target_word": "線", "complexity_tier": "T3", "furigana": "せん うし なら", "sentence_source": "generated"}], "morphological_forms": [{"form": "本", "label": "助数詞"}, {"form": "線を引く", "label": "派生"}, {"form": "曲線", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 細く長く引いたすじ・ライン", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', t