INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35938, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "音楽の音符などを書いた紙。楽譜。", "primary_collocate": null, "pronunciation": "ふ", "ipa": "ɸɯ", "syllable_count": 1, "sentences": [{"text": "ピアノの上に譜を置いた。", "target_word": "譜", "complexity_tier": "T3", "furigana": "うえ ふ お", "sentence_source": "generated"}, {"text": "彼は譜を見ながら歌った。", "target_word": "譜", "complexity_tier": "T3", "furigana": "かれ ふ み うた", "sentence_source": "generated"}, {"text": "新しい曲の譜をもらった。", "target_word": "譜", "complexity_tier": "T3", "furigana": "あたら きょく ふ", "sentence_source": "generated"}, {"text": "譜を忘れて練習できなかった。", "target_word": "譜", "complexity_tier": "T3", "furigana": "ふ わす れんしゅう", "sentence_source": "generated"}, {"text": "この譜は少し読みにくい。", "target_word": "譜", "complexity_tier": "T3", "furigana": "ふ すこ よ", "sentence_source": "generated"}, {"text": "先生が譜を一枚コピーした。", "target_word": "譜", "complexity_tier": "T3", "furigana": "せんせい ふ いちまい", "sentence_source": "generated"}, {"text": "譜をめくるのを手伝ってくれた。", "target_word": "譜", "complexity_tier": "T3", "furigana": "ふ てつだ", "sentence_source": "generated"}, {"text": "古い譜がかばんに入っている。", "target_word": "譜", "complexity_tier": "T3", "furigana": "ふる ふ はい", "sentence_source": "generated"}, {"text": "彼女は譜なしでギターをひく。", "target_word": "譜", "complexity_tier": "T3", "furigana": "かのじょ ふ", "sentence_source": "generated"}, {"text": "譜に鉛筆で印をつけた。", "target_word": "譜", "complexity_tier": "T3", "furigana": "ふ えんぴつ しるし", "sentence_source": "generated"}], "morphological_forms": [{"form": "枚", "label": "助数詞"}, {"form": "楽譜", "label": "派生"}, {"form": "譜面", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 音楽を書き記した紙・楽譜", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1d18