INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35936, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "線", "is_correct": true, "explanation": "正解。「せん」と読む。"}, {"text": "席", "is_correct": false, "explanation": "「せき」と読み、座る場所。音が一拍だけ違う。"}, {"text": "券", "is_correct": false, "explanation": "「けん」と読み、切符のこと。音が一拍だけ違う。"}, {"text": "全", "is_correct": false, "explanation": "「ぜん」と読み、すべての意味。音が一拍だけ違う。"}, {"text": "天", "is_correct": false, "explanation": "「てん」と読み、空のこと。音が一拍だけ違う。"}], "explanations": {"線": "正解。「せん」と読む。", "席": "「せき」と読み、座る場所。音が一拍だけ違う。", "券": "「けん」と読み、切符のこと。音が一拍だけ違う。", "全": "「ぜん」と読み、すべての意味。音が一拍だけ違う。", "天": "「てん」と読み、空のこと。音が一拍だけ違う。"}, "sentence_index": null, "correct_answer": "線"}, "level_3": {"options": [{"text": "線", "is_correct": true, "explanation": "「線を引く」と言い、まっすぐなすじを表す。"}, {"text": "音", "is_correct": false, "explanation": "音は引くものではなく、聞くものだ。"}, {"text": "窓", "is_correct": false, "explanation": "窓はノートに引くことができない。"}, {"text": "夢", "is_correct": false, "explanation": "夢はノートに引くことができない。"}], "explanations": {"線": "「線を引く」と言い、まっすぐなすじを表す。", "音": "音は引くものではなく、聞くものだ。", "窓": "窓はノートに引くことができない。", "夢": "夢はノートに引くことができない。"}, "sentence_index": 0, "correct_answer": "線"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この線はとても甘くておいしい。", "explanation": "線は食べ物ではないので、味はない。"}, {"text": "線が大きな声で歌っている。", "explanation": "線は生き物ではないので、歌わない。"}, {"text": "私は毎朝、線を飲んでいる。", "explanation": "線は飲み物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '202dfbf3-1409-471d-8608-d00230db9672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
