INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35940, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "点", "is_correct": true, "explanation": "正解。「てん」と読む。"}, {"text": "線", "is_correct": false, "explanation": "「せん」と読み、細長いすじ。音が一拍だけ違う。"}, {"text": "券", "is_correct": false, "explanation": "「けん」と読み、切符。音が一拍だけ違う。"}, {"text": "円", "is_correct": false, "explanation": "「えん」と読み、お金の単位。音が一拍だけ違う。"}, {"text": "敵", "is_correct": false, "explanation": "「てき」と読み、戦う相手。音が一拍だけ違う。"}], "explanations": {"点": "正解。「てん」と読む。", "線": "「せん」と読み、細長いすじ。音が一拍だけ違う。", "券": "「けん」と読み、切符。音が一拍だけ違う。", "円": "「えん」と読み、お金の単位。音が一拍だけ違う。", "敵": "「てき」と読み、戦う相手。音が一拍だけ違う。"}, "sentence_index": null, "correct_answer": "点"}, "level_3": {"options": [{"text": "点", "is_correct": true, "explanation": "紙に付ける小さな丸い印。"}, {"text": "音", "is_correct": false, "explanation": "音は紙につけられない。"}, {"text": "風", "is_correct": false, "explanation": "風は紙につけられない。"}, {"text": "夢", "is_correct": false, "explanation": "夢は紙につけられない。"}], "explanations": {"点": "紙に付ける小さな丸い印。", "音": "音は紙につけられない。", "風": "風は紙につけられない。", "夢": "夢は紙につけられない。"}, "sentence_index": 0, "correct_answer": "点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "点が大きな声で歌った。", "explanation": "点は人ではない。"}, {"text": "点をコップで飲んだ。", "explanation": "点は飲み物ではない。"}, {"text": "点に乗って駅まで行った。", "explanation": "点は乗り物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '202dfbf3-1409-471d-8608-d00230db9672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
