INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35960, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "決める", "is_correct": true, "explanation": "正解。「きめる」と読む。"}, {"text": "閉める", "is_correct": false, "explanation": "「しめる」と読み、戸などをしめる。音が一拍だけ違う。"}, {"text": "切れる", "is_correct": false, "explanation": "「きれる」と読み、切ることができる・糸が切れる。音が一拍だけ違う。"}, {"text": "貯める", "is_correct": false, "explanation": "「ためる」と読み、お金をたくわえる。音が一拍だけ違う。"}, {"text": "攻める", "is_correct": false, "explanation": "「せめる」と読み、相手を攻撃する。音が一拍だけ違う。"}], "explanations": {"決める": "正解。「きめる」と読む。", "閉める": "「しめる」と読み、戸などをしめる。音が一拍だけ違う。", "切れる": "「きれる」と読み、切ることができる・糸が切れる。音が一拍だけ違う。", "貯める": "「ためる」と読み、お金をたくわえる。音が一拍だけ違う。", "攻める": "「せめる」と読み、相手を攻撃する。音が一拍だけ違う。"}, "sentence_index": null, "correct_answer": "決める"}, "level_3": {"options": [{"text": "決めた", "is_correct": true, "explanation": "予定をはっきりさせたので「決めた」。"}, {"text": "食べた", "is_correct": false, "explanation": "予定は食べられない。"}, {"text": "走った", "is_correct": false, "explanation": "予定を走るとは言わない。"}, {"text": "眠った", "is_correct": false, "explanation": "予定を眠るとは言わない。"}], "explanations": {"決めた": "予定をはっきりさせたので「決めた」。", "食べた": "予定は食べられない。", "走った": "予定を走るとは言わない。", "眠った": "予定を眠るとは言わない。"}, "sentence_index": 0, "correct_answer": "決めた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "部屋の電気を決めて明るくした。", "explanation": "電気は「つける」で、「決める」ではない。"}, {"text": "雨が決めてきたので傘をさした。", "explanation": "雨は「降る」で、「決める」ではない。"}, {"text": "コップに水を決めた。", "explanation": "水は「入れる」で、「決める」ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '202dfbf3-1409-471d-8608-d00230db9672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
