INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35960, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "決める", "is_correct": true, "explanation": "正解。「きめる」と読む。"}, {"text": "止める", "is_correct": false, "explanation": "「とめる」と読み、動きをやめさせる。音が一拍だけ違う。"}, {"text": "着せる", "is_correct": false, "explanation": "「きせる」と読み、人に服を着させる。音が一拍だけ違う。"}, {"text": "褒める", "is_correct": false, "explanation": "「ほめる」と読み、よいと言う。音が一拍だけ違う。"}, {"text": "冷める", "is_correct": false, "explanation": "「さめる」と読み、温度が下がる。音が一拍だけ違う。"}], "explanations": {"決める": "正解。「きめる」と読む。", "止める": "「とめる」と読み、動きをやめさせる。音が一拍だけ違う。", "着せる": "「きせる」と読み、人に服を着させる。音が一拍だけ違う。", "褒める": "「ほめる」と読み、よいと言う。音が一拍だけ違う。", "冷める": "「さめる」と読み、温度が下がる。音が一拍だけ違う。"}, "sentence_index": null, "correct_answer": "決める"}, "level_3": {"options": [{"text": "決めた", "is_correct": true, "explanation": "医者になることを選んだので「決めた」。"}, {"text": "走った", "is_correct": false, "explanation": "「なると走った」は意味が通らない。"}, {"text": "洗った", "is_correct": false, "explanation": "「なると洗った」は意味が通らない。"}, {"text": "眠った", "is_correct": false, "explanation": "「なると眠った」は意味が通らない。"}], "explanations": {"決めた": "医者になることを選んだので「決めた」。", "走った": "「なると走った」は意味が通らない。", "洗った": "「なると洗った」は意味が通らない。", "眠った": "「なると眠った」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "決めた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寝る前に歯を決めた。", "explanation": "歯は「みがく」で、「決める」ではない。"}, {"text": "風が強く決めている。", "explanation": "風は「吹く」で、「決める」ではない。"}, {"text": "お風呂でお湯を決めた。", "explanation": "お湯は「わかす」で、「決める」ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '202dfbf3-1409-471d-8608-d00230db9672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnin