INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35960, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は医者になると決めった。", "corrected_sentence": "彼は医者になると決めた。", "error_description": "「決める」は一段動詞で、た形は「決めた」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "決められ", "is_correct": true, "explanation": "「ない」に続く可能形で、できないことを表す。"}, {"text": "決めた", "is_correct": false, "explanation": "た形の後に「ない」は続かない。"}, {"text": "決める", "is_correct": false, "explanation": "辞書形の後に「ない」は続かない。"}, {"text": "決めよう", "is_correct": false, "explanation": "意向形の後に「ない」は続かない。"}], "correct_form": "決められ", "base_form": "決める", "form_label": "可能形", "sentence_index": 7, "explanations": {"決められ": "「ない」に続く可能形で、できないことを表す。", "決めた": "た形の後に「ない」は続かない。", "決める": "辞書形の後に「ない」は続かない。", "決めよう": "意向形の後に「ない」は続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '202dfbf3-1409-471d-8608-d00230db9672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
