INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35962, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "音楽をえんそうするときにみる、せんとしるしがかいてあるもの", "primary_collocate": null, "pronunciation": "がくふ", "ipa": "ɡakɯɸɯ", "syllable_count": 3, "sentences": [{"text": "楽譜を見ながらピアノをひいている。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "がくふ", "sentence_source": "generated"}, {"text": "先生が新しい楽譜をくれた。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "せんせい あたら がくふ", "sentence_source": "generated"}, {"text": "私はまだ楽譜が読めない。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "わたし がくふ よ", "sentence_source": "generated"}, {"text": "楽譜をかばんに入れて学校へ行く。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "がくふ い がっこう い", "sentence_source": "generated"}, {"text": "この楽譜はとても古い。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "がくふ ふる", "sentence_source": "generated"}, {"text": "姉は楽譜なしでギターをひける。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "あね がくふ", "sentence_source": "generated"}, {"text": "楽譜の読み方を習っている。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "がくふ よ かた なら", "sentence_source": "generated"}, {"text": "机の上に楽譜が置いてある。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "つくえ うえ がくふ お", "sentence_source": "generated"}, {"text": "合唱の楽譜を全員に配った。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "がっしょう がくふ ぜんいん くば", "sentence_source": "generated"}, {"text": "楽譜をコピーして練習した。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "がくふ れんしゅう", "sentence_source": "generated"}], "morphological_forms": [{"form": "枚", "label": "助数詞"}, {"form": "冊", "label": "助数詞"}, {"form": "楽譜集", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 演奏のとき見る音楽の記号の紙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb