INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35963, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "音楽の演奏方法を記号で書き表したもの。曲を再現するための情報が書かれている", "primary_collocate": null, "pronunciation": "がくふ", "ipa": "ɡakɯɸɯ", "syllable_count": 3, "sentences": [{"text": "作曲家は自分の曲を楽譜に書いた。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "さっきょくか じぶん きょく がくふ か", "sentence_source": "generated"}, {"text": "楽譜には音の長さも書いてある。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "がくふ おと なが か", "sentence_source": "generated"}, {"text": "古い楽譜から昔の曲を再現できる。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "ふる がくふ むかし きょく さいげん", "sentence_source": "generated"}, {"text": "この曲の楽譜は手に入らない。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "きょく がくふ て はい", "sentence_source": "generated"}, {"text": "楽譜の記号の意味を調べている。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "がくふ きごう いみ しら", "sentence_source": "generated"}, {"text": "彼は聞いた曲をすぐ楽譜にできる。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "かれ き きょく がくふ", "sentence_source": "generated"}, {"text": "図書館で楽譜を借りてきた。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "としょかん がくふ か", "sentence_source": "generated"}, {"text": "楽譜どおりに演奏するのは難しい。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "がくふ えんそう むずか", "sentence_source": "generated"}, {"text": "バンドの楽譜を自分で作った。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "がくふ じぶん つく", "sentence_source": "generated"}, {"text": "楽譜が読めると練習が楽になる。", "target_word": "楽譜", "complexity_tier": "T3", "furigana": "がくふ よ れんしゅう らく", "sentence_source": "generated"}], "morphological_forms": [{"form": "枚", "label": "助数詞"}, {"form": "冊", "label": "助数詞"}, {"form": "楽譜集", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 曲を記号で書き表した記録", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a4d1b3-8c4b-4d8a-b78c-ca93729dc0b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35964, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "前のことが、あとにそのままうつって現れること", "primary_collocate": null, "pronunciation": "はんえい", "ipa": "haɴeː", "syllable_count": 4, "sentences": [{"text": "練習の成果が試合に反映された。", "target_word": "反映", "complexity_tier": "T3", "furigana": "れんしゅう せいか しあい はんえい", "sentence_source": "generated"}, {"text": "親の性格が子どもに反映する。", "target_word": "反映", "complexity_tier": "T3", "furigana": "おや せいかく こ はんえい", "sentence_source": "generated"}, {"text": "天気が気分に反映することもある。", "target_word": "反映", "complexity_tier": "T3", "furigana": "てんき きぶん はんえい", "sentence_source": "generated"}, {"text": "努力の反映が成績に出ている。", "target_word": "反映", "complexity_tier": "T3", "furigana": "どりょく はんえい せいせき で", "sentence_source": "generated"}, {"text": "失敗の経験が今の仕事に反映している。", "target_word": "反映", "complexity_tier": "T3", "furigana": "しっぱい けいけん いま しごと はんえい", "sentence_source": "generated"}, {"text": "子どもの考えが絵に反映している。", "target_word": "反映", "complexity_tier": "T3", "furigana": "こ かんが え はんえい", "sentence_source": "generated"}, {"text": "結果の反映には時間がかかる。", "target_word": "反映", "complexity_tier": "T3", "furigana": "けっか はんえい じかん", "sentence_source": "generated"}, {"text": "その努力は新しい作品に反映された。", "target_word": "反映", "complexity_tier": "T3", "furigana": "どりょく あたら さくひん はんえい", "sentence_source": "generated"}, {"text": "生活の変化が言葉に反映される。", "target_word": "反映", "complexity_tier": "T3", "furigana": "せいかつ へんか ことば はんえい", "sentence_source": "generated"}, {"text": "反映されたのは一部だけだった。", "target_word": "反映", "complexity_tier": "T3", "furigana": "はんえい いちぶ", "sentence_source": "generated"}], "morphological_forms": [{"form": "反映する", "label": "派生"}, {"form": "反映される", "label": "活用"}, {"form": "反映させる", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 前のことが後にそのまま現れること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a4d1b3-8c4b-4d8a-b78c-ca93729dc0b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35965, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "前の出来事や考え方を、あとのものにそのまま取り入れること", "primary_collocate": null, "pronunciation": "はんえい", "ipa": "haɴeː", "syllable_count": 4, "sentences": [{"text": "アンケートの結果を授業に反映する。", "target_word": "反映", "complexity_tier": "T3", "furigana": "けっか じゅぎょう はんえい", "sentence_source": "generated"}, {"text": "社会の考え方を映画に反映している。", "target_word": "反映", "complexity_tier": "T3", "furigana": "しゃかい かんが かた えいが はんえい", "sentence_source": "generated"}, {"text": "生徒の声を反映した校則ができた。", "target_word": "反映", "complexity_tier": "T3", "furigana": "せいと こえ はんえい こうそく", "sentence_source": "generated"}, {"text": "昔の出来事を今の町づくりに反映している。", "target_word": "反映", "complexity_tier": "T3", "furigana": "むかし できごと いま まち はんえい", "sentence_source": "generated"}, {"text": "意見の反映がまだ足りないと思う。", "target_word": "反映", "complexity_tier": "T3", "furigana": "いけん はんえい た おも", "sentence_source": "generated"}, {"text": "経験を反映して練習方法を変えた。", "target_word": "反映", "complexity_tier": "T3", "furigana": "けいけん はんえい れんしゅう ほうほう か", "sentence_source": "generated"}, {"text": "作者の気持ちが歌詞に反映されている。", "target_word": "反映", "complexity_tier": "T3", "furigana": "さくしゃ きも かし はんえい", "sentence_source": "generated"}, {"text": "変更はすぐに反映されない。", "target_word": "反映", "complexity_tier": "T3", "furigana": "へんこう はんえい", "sentence_source": "generated"}, {"text": "反映するかどうかは会議で決める。", "target_word": "反映", "complexity_tier": "T3", "furigana": "はんえい かいぎ き", "sentence_source": "generated"}, {"text": "生徒の意見の反映が求められている。", "target_word": "反映", "complexity_tier": "T3", "furigana": "せいと いけん はんえい もと", "sentence_source": "generated"}], "morphological_forms": [{"form": "反映する", "label": "派生"}, {"form": "反映される", "label": "活用"}, {"form": "反映させる", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 意見や考えを後のものに取り入れること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a4d1b3-8c4b-4d8a-b78c-ca93729dc0b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
