INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36053, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "複数のパートに分かれた曲の、それぞれの旋律の部分。", "primary_collocate": null, "pronunciation": "せいぶ", "ipa": "seːbɯ", "syllable_count": 3, "sentences": [{"text": "この合唱曲には三つの声部がある。", "target_word": "声部", "complexity_tier": "T3", "furigana": "せいぶ", "sentence_source": "generated"}, {"text": "内側の声部は聞き取りにくい。", "target_word": "声部", "complexity_tier": "T3", "furigana": "せいぶ", "sentence_source": "generated"}, {"text": "声部の動きを楽譜で確かめた。", "target_word": "声部", "complexity_tier": "T3", "furigana": "せいぶ", "sentence_source": "generated"}, {"text": "各声部が違うメロディーを歌う。", "target_word": "声部", "complexity_tier": "T3", "furigana": "せいぶ", "sentence_source": "generated"}, {"text": "低い声部が曲を支えている。", "target_word": "声部", "complexity_tier": "T3", "furigana": "せいぶ", "sentence_source": "generated"}, {"text": "バッハの曲は声部が多い。", "target_word": "声部", "complexity_tier": "T3", "furigana": "せいぶ", "sentence_source": "generated"}, {"text": "僕たちの声部は少し遅れた。", "target_word": "声部", "complexity_tier": "T3", "furigana": "せいぶ", "sentence_source": "generated"}, {"text": "声部どうしの音が重なっている。", "target_word": "声部", "complexity_tier": "T3", "furigana": "せいぶ", "sentence_source": "generated"}, {"text": "彼は一つの声部をピアノで弾いた。", "target_word": "声部", "complexity_tier": "T3", "furigana": "せいぶ", "sentence_source": "generated"}, {"text": "声部を一つずつ聞いてみよう。", "target_word": "声部", "complexity_tier": "T3", "furigana": "せいぶ", "sentence_source": "generated"}], "morphological_forms": [{"form": "声部数", "label": "派生"}, {"form": "各声部", "label": "派生"}, {"form": "一声部", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 多声曲の各旋律部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d0caa-5d0e-4fd