INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36060, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "あるものを使うことに決めて、取り入れること。", "primary_collocate": null, "pronunciation": "さいよう", "ipa": "saijoː", "syllable_count": 4, "sentences": [{"text": "私の意見が採用された。", "target_word": "採用", "complexity_tier": "T3", "furigana": "さいよう", "sentence_source": "generated"}, {"text": "学校は新しい制服の採用を決めた。", "target_word": "採用", "complexity_tier": "T3", "furigana": "さいよう", "sentence_source": "generated"}, {"text": "その案は採用されなかった。", "target_word": "採用", "complexity_tier": "T3", "furigana": "さいよう", "sentence_source": "generated"}, {"text": "会社は新しい方法を採用した。", "target_word": "採用", "complexity_tier": "T3", "furigana": "さいよう", "sentence_source": "generated"}, {"text": "採用の理由を説明してください。", "target_word": "採用", "complexity_tier": "T3", "furigana": "さいよう", "sentence_source": "generated"}, {"text": "みんなの案から一つを採用した。", "target_word": "採用", "complexity_tier": "T3", "furigana": "さいよう", "sentence_source": "generated"}, {"text": "この教科書の採用は来年からだ。", "target_word": "採用", "complexity_tier": "T3", "furigana": "さいよう", "sentence_source": "generated"}, {"text": "採用が決まってうれしかった。", "target_word": "採用", "complexity_tier": "T3", "furigana": "さいよう", "sentence_source": "generated"}, {"text": "彼のアイデアの採用に賛成だ。", "target_word": "採用", "complexity_tier": "T3", "furigana": "さいよう", "sentence_source": "generated"}, {"text": "市は新しいルールを採用している。", "target_word": "採用", "complexity_tier": "T3", "furigana": "さいよう", "sentence_source": "generated"}], "morphological_forms": [{"form": "採用する", "label": "派生"}, {"form": "採用される", "label": "活用"}, {"form": "不採用", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 使うと決めて取り入れること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8