INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36062, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある状態や仕組みから、別のものに移り変わること。", "primary_collocate": null, "pronunciation": "いこう", "ipa": "ikoː", "syllable_count": 3, "sentences": [{"text": "新しいシステムへの移行が始まった。", "target_word": "移行", "complexity_tier": "T3", "furigana": "いこう", "sentence_source": "generated"}, {"text": "移行には少し時間がかかる。", "target_word": "移行", "complexity_tier": "T3", "furigana": "いこう", "sentence_source": "generated"}, {"text": "町は新しい制度に移行した。", "target_word": "移行", "complexity_tier": "T3", "furigana": "いこう", "sentence_source": "generated"}, {"text": "移行の準備を急いでいる。", "target_word": "移行", "complexity_tier": "T3", "furigana": "いこう", "sentence_source": "generated"}, {"text": "授業はオンラインに移行している。", "target_word": "移行", "complexity_tier": "T3", "furigana": "いこう", "sentence_source": "generated"}, {"text": "スムーズな移行ができた。", "target_word": "移行", "complexity_tier": "T3", "furigana": "いこう", "sentence_source": "generated"}, {"text": "移行の時期は来月だ。", "target_word": "移行", "complexity_tier": "T3", "furigana": "いこう", "sentence_source": "generated"}, {"text": "会社は紙から電子に移行した。", "target_word": "移行", "complexity_tier": "T3", "furigana": "いこう", "sentence_source": "generated"}, {"text": "この移行で仕事が楽になる。", "target_word": "移行", "complexity_tier": "T3", "furigana": "いこう", "sentence_source": "generated"}, {"text": "移行がうまくいって安心した。", "target_word": "移行", "complexity_tier": "T3", "furigana": "いこう", "sentence_source": "generated"}], "morphological_forms": [{"form": "移行する", "label": "派生"}, {"form": "移行期", "label": "派生"}, {"form": "移行中", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 別の状態へ移り変わること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d0caa-5d0e-4fd1-a468-7