INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36064, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "音楽で、音符が表す音の長さ。", "primary_collocate": null, "pronunciation": "おんか", "ipa": "oŋka", "syllable_count": 3, "sentences": [{"text": "四分音符の音価は全音符より短い。", "target_word": "音価", "complexity_tier": "T3", "furigana": "おんか", "sentence_source": "generated"}, {"text": "音価を正しく数えて弾こう。", "target_word": "音価", "complexity_tier": "T3", "furigana": "おんか", "sentence_source": "generated"}, {"text": "この音符の音価が分からない。", "target_word": "音価", "complexity_tier": "T3", "furigana": "おんか", "sentence_source": "generated"}, {"text": "音価が長い音はゆっくり伸ばす。", "target_word": "音価", "complexity_tier": "T3", "furigana": "おんか", "sentence_source": "generated"}, {"text": "先生は音価について説明した。", "target_word": "音価", "complexity_tier": "T3", "furigana": "おんか", "sentence_source": "generated"}, {"text": "全音符は音価が一番長い。", "target_word": "音価", "complexity_tier": "T3", "furigana": "おんか", "sentence_source": "generated"}, {"text": "音価を間違えてリズムが崩れた。", "target_word": "音価", "complexity_tier": "T3", "furigana": "おんか", "sentence_source": "generated"}, {"text": "楽譜で音価を確かめた。", "target_word": "音価", "complexity_tier": "T3", "furigana": "おんか", "sentence_source": "generated"}, {"text": "付点は音価を長くする。", "target_word": "音価", "complexity_tier": "T3", "furigana": "おんか", "sentence_source": "generated"}, {"text": "音価の違いを手でたたいて覚えた。", "target_word": "音価", "complexity_tier": "T3", "furigana": "おんか", "sentence_source": "generated"}], "morphological_forms": [{"form": "音価記号", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 音符が表す音の長さ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d0caa-5d0e-4fd1-a468-7a4ee16c62f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content =