INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36068, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "頭の中で、まだ見ていない様子を、くわしく考えること。", "primary_collocate": null, "pronunciation": "おもいえがく", "ipa": "omoiegakɯ", "syllable_count": 6, "sentences": [{"text": "将来の自分を思い描く。", "target_word": "思い描く", "complexity_tier": "T3", "furigana": "しょうらい じぶん おも えが", "sentence_source": "generated"}, {"text": "新しい家を思い描いている。", "target_word": "思い描い", "complexity_tier": "T3", "furigana": "あたら いえ おも えが", "sentence_source": "generated"}, {"text": "海の景色を思い描いた。", "target_word": "思い描い", "complexity_tier": "T3", "furigana": "うみ けしき おも えが", "sentence_source": "generated"}, {"text": "思い描いた夢がかなった。", "target_word": "思い描い", "complexity_tier": "T3", "furigana": "おも えが ゆめ", "sentence_source": "generated"}, {"text": "彼の顔をうまく思い描けない。", "target_word": "思い描け", "complexity_tier": "T3", "furigana": "かれ かお おも えが", "sentence_source": "generated"}, {"text": "目を閉じて、町を思い描く。", "target_word": "思い描く", "complexity_tier": "T3", "furigana": "め と まち おも えが", "sentence_source": "generated"}, {"text": "旅行の計画を思い描いてみた。", "target_word": "思い描い", "complexity_tier": "T3", "furigana": "りょこう けいかく おも えが", "sentence_source": "generated"}, {"text": "思い描く未来は明るい。", "target_word": "思い描く", "complexity_tier": "T3", "furigana": "おも えが みらい あか", "sentence_source": "generated"}, {"text": "昔の村を思い描きながら話す。", "target_word": "思い描き", "complexity_tier": "T3", "furigana": "むかし むら おも えが はな", "sentence_source": "generated"}, {"text": "試合に勝つ姿を思い描こう。", "target_word": "思い描こ", "complexity_tier": "T3", "furigana": "しあい か すがた おも えが", "sentence_source": "generated"}], "morphological_forms": [{"form": "思い描いた", "label": "活用"}, {"form": "思い描いて", "label": "活用"}, {"form": "思い描かない", "label": "活用"}, {"form": "思い描ける", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 見ていない様子を頭の中で考える", "collocate_grounding