INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36069, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "心に情景やイメージを浮かべること。想像すること。", "primary_collocate": null, "pronunciation": "おもいえがく", "ipa": "omoiegakɯ", "syllable_count": 6, "sentences": [{"text": "楽しい夏休みを思い描く。", "target_word": "思い描く", "complexity_tier": "T3", "furigana": "たの なつやす おも えが", "sentence_source": "generated"}, {"text": "理想の部屋を思い描いている。", "target_word": "思い描い", "complexity_tier": "T3", "furigana": "りそう へや おも えが", "sentence_source": "generated"}, {"text": "母の笑顔を心に思い描いた。", "target_word": "思い描い", "complexity_tier": "T3", "furigana": "はは えがお こころ おも えが", "sentence_source": "generated"}, {"text": "思い描いたとおりの絵ができた。", "target_word": "思い描い", "complexity_tier": "T3", "furigana": "おも えが え", "sentence_source": "generated"}, {"text": "十年後の町は思い描けない。", "target_word": "思い描け", "complexity_tier": "T3", "furigana": "じゅうねん ご まち おも えが", "sentence_source": "generated"}, {"text": "星空を思い描くと落ち着く。", "target_word": "思い描く", "complexity_tier": "T3", "furigana": "ほしぞら おも えが お つ", "sentence_source": "generated"}, {"text": "物語の場面を思い描いて読む。", "target_word": "思い描い", "complexity_tier": "T3", "furigana": "ものがたり ばめん おも えが よ", "sentence_source": "generated"}, {"text": "彼女が思い描く世界は美しい。", "target_word": "思い描く", "complexity_tier": "T3", "furigana": "かのじょ おも えが せかい うつく", "sentence_source": "generated"}, {"text": "大人になった姿を思い描きます。", "target_word": "思い描き", "complexity_tier": "T3", "furigana": "おとな すがた おも えが", "sentence_source": "generated"}, {"text": "もっと自由に思い描こう。", "target_word": "思い描こ", "complexity_tier": "T3", "furigana": "じゆう おも えが", "sentence_source": "generated"}], "morphological_forms": [{"form": "思い描いた", "label": "活用"}, {"form": "思い描いて", "label": "活用"}, {"form": "思い描かない", "label": "活用"}, {"form": "思い描ける", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 心にイメージを浮かべて想像する", "coll