INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36065, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "音価", "is_correct": true, "explanation": "おんか。音符が示す音の長さ。"}, {"text": "演歌", "is_correct": false, "explanation": "えんか。一拍目の「お」が「え」に変わる一モーラ差。"}, {"text": "温度", "is_correct": false, "explanation": "おんど。三拍目の「か」が「ど」に変わる一モーラ差。"}, {"text": "恩師", "is_correct": false, "explanation": "おんし。三拍目の「か」が「し」に変わる一モーラ差。"}, {"text": "引火", "is_correct": false, "explanation": "いんか。一拍目の「お」が「い」に変わる一モーラ差。"}], "explanations": {"音価": "おんか。音符が示す音の長さ。", "演歌": "えんか。一拍目の「お」が「え」に変わる一モーラ差。", "温度": "おんど。三拍目の「か」が「ど」に変わる一モーラ差。", "恩師": "おんし。三拍目の「か」が「し」に変わる一モーラ差。", "引火": "いんか。一拍目の「お」が「い」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "音価"}, "level_3": {"options": [{"text": "音価", "is_correct": true, "explanation": "四分音符が示す長さなので「音価」が入る。"}, {"text": "音量", "is_correct": false, "explanation": "意味：音量は音の大きさで、音符の長さではない。"}, {"text": "音色", "is_correct": false, "explanation": "意味：音色は音の性質で、一拍とは言わない。"}, {"text": "音程", "is_correct": false, "explanation": "意味：音程は高さの差で、拍で表さない。"}], "explanations": {"音価": "四分音符が示す長さなので「音価」が入る。", "音量": "意味：音量は音の大きさで、音符の長さではない。", "音色": "意味：音色は音の性質で、一拍とは言わない。", "音程": "意味：音程は高さの差で、拍で表さない。"}, "sentence_index": 0, "correct_answer": "音価"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この休符の音価は大きくて耳が痛い。", "explanation": "意味の誤り：音価は長さであり、音の大きさではない。"}, {"text": "四分音符が音価を一拍です。", "explanation": "助詞の誤り：「音価は一拍です」とすべき。"}, {"text": "音価を一冊ずつ数える。", "explanation": "助数詞の誤り：音価は本ではないので「冊」で数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59aa89a-a9b4-4f65-80dc-a6bcb4d0dd78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings 