DED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36068, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい家が思い描いている。", "corrected_sentence": "新しい家を思い描いている。", "error_description": "助詞の誤り：「思い描く」の目的語は「を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "思い描い", "is_correct": true, "explanation": "「ている」に続くて形の語幹。"}, {"text": "思い描か", "is_correct": false, "explanation": "ない形の語幹で、「ている」には続かない。"}, {"text": "思い描け", "is_correct": false, "explanation": "可能・命令の形で、「ている」には続かない。"}, {"text": "思い描こ", "is_correct": false, "explanation": "意向形の語幹で、「ている」には続かない。"}], "correct_form": "思い描い", "base_form": "思い描く", "form_label": "て形", "sentence_index": 1, "explanations": {"思い描い": "「ている」に続くて形の語幹。", "思い描か": "ない形の語幹で、「ている」には続かない。", "思い描け": "可能・命令の形で、「ている」には続かない。", "思い描こ": "意向形の語幹で、「ている」には続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59aa89a-a9b4-4f65-80dc-a6bcb4d0dd78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36068, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「思い描く」の目的語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「家に思い描いている」は非文。"}, {"text": "で", "is_correct": false, "explanation": "「家で」は場所になり、何を思い描くかがなくなる。"}, {"text": "が", "is_correct": false, "explanation": "「家が思い描いている」では家が想像する主体になり不自然。"}], "correct_answer": "を", "explanations": {"を": "「思い描く」の目的語を示す。", "に": "「家に思い描いている」は非文。", "で": "「家で」は場所になり、何を思い描くかがなくなる。", "が": "「家が思い描いている」では家が想像する主体になり不自然。"}, "error_tags": {"に": "location_vs_target", "で": "location_vs_target", "が": "object_marking"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59aa89a-a9b4-4f65-80dc-a6bcb4d0dd78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36068, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "思い描く", "is_correct": true, "explanation": "おもいえがく。想像すること。"}, {"text": "思い悩む", "is_correct": false, "explanation": "おもいなやむ。後半の音が違う。くよくよ悩むこと。"}, {"text": "思い込む", "is_correct": false, "explanation": "おもいこむ。後半の音が違う。強く信じること。"}, {"text": "思い出す", "is_correct": false, "explanation": "おもいだす。後半の音が違う。記憶を呼び起こすこと。"}], "explanations": {"思い描く": "おもいえがく。想像すること。", "思い悩む": "おもいなやむ。後半の音が違う。くよくよ悩むこと。", "思い込む": "おもいこむ。後半の音が違う。強く信じること。", "思い出す": "おもいだす。後半の音が違う。記憶を呼び起こすこと。"}, "sentence_index": null, "correct_answer": "思い描く"}, "level_3": {"options": [{"text": "思い描い", "is_correct": true, "explanation": "「てみた」に続くて形の語幹。"}, {"text": "泳い", "is_correct": false, "explanation": "項構造：泳ぐは目的語「計画を」をとれない。"}, {"text": "食べ", "is_correct": false, "explanation": "意味：計画は食べられない。"}, {"text": "洗っ", "is_correct": false, "explanation": "連語：「計画を洗う」とは言わない。"}], "explanations": {"思い描い": "「てみた」に続くて形の語幹。", "泳い": "項構造：泳ぐは目的語「計画を」をとれない。", "食べ": "意味：計画は食べられない。", "洗っ": "連語：「計画を洗う」とは言わない。"}, "sentence_index": 6, "correct_answer": "思い描い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合に勝つ姿が思い描こう。", "explanation": "助詞の誤り：「姿を思い描こう」とすべき。"}, {"text": "試合に勝つ姿を二冊思い描こう。", "explanation": "助数詞の誤り：姿を「冊」で数えない。"}, {"text": "試合に勝つ姿を思い描かよう。", "explanation": "活用の誤り：意向形は「思い描こう」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59aa89a-a9b4-4f65-80dc-a6bcb4d0dd78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
