INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36069, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "星空を思い描くが落ち着く。", "corrected_sentence": "星空を思い描くと落ち着く。", "error_description": "助詞の誤り：条件を表す「と」を使う。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "思い描く", "is_correct": true, "explanation": "名詞「世界」を修飾する辞書形（連体形）。"}, {"text": "思い描いて", "is_correct": false, "explanation": "て形は名詞を直接修飾できない。"}, {"text": "思い描こう", "is_correct": false, "explanation": "意向形は名詞を直接修飾しない。"}, {"text": "思い描け", "is_correct": false, "explanation": "命令形は名詞を修飾できない。"}], "correct_form": "思い描く", "base_form": "思い描く", "form_label": "辞書形", "sentence_index": 7, "explanations": {"思い描く": "名詞「世界」を修飾する辞書形（連体形）。", "思い描いて": "て形は名詞を直接修飾できない。", "思い描こう": "意向形は名詞を直接修飾しない。", "思い描け": "命令形は名詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59aa89a-a9b4-4f65-80dc-a6bcb4d0dd78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36069, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "連体修飾節の中で、思い描く人（主語）を示す。"}, {"text": "に", "is_correct": false, "explanation": "「彼女に思い描く」は非文。"}, {"text": "で", "is_correct": false, "explanation": "「彼女で思い描く」は非文。"}, {"text": "へ", "is_correct": false, "explanation": "「彼女へ思い描く」は非文。"}], "correct_answer": "が", "explanations": {"が": "連体修飾節の中で、思い描く人（主語）を示す。", "に": "「彼女に思い描く」は非文。", "で": "「彼女で思い描く」は非文。", "へ": "「彼女へ思い描く」は非文。"}, "error_tags": {"に": "location_vs_target", "で": "instrument", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59aa89a-a9b4-4f65-80dc-a6bcb4d0dd78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36070, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "微細", "is_correct": true, "explanation": "びさい。とても細かいこと。"}, {"text": "被災", "is_correct": false, "explanation": "ひさい。一拍目「び」→「ひ」の清濁の違い。"}, {"text": "記載", "is_correct": false, "explanation": "きさい。一拍目「び」→「き」の一モーラ差。"}, {"text": "委細", "is_correct": false, "explanation": "いさい。一拍目「び」→「い」の一モーラ差。"}], "explanations": {"微細": "びさい。とても細かいこと。", "被災": "ひさい。一拍目「び」→「ひ」の清濁の違い。", "記載": "きさい。一拍目「び」→「き」の一モーラ差。", "委細": "いさい。一拍目「び」→「い」の一モーラ差。"}, "sentence_index": null, "correct_answer": "微細"}, "level_3": {"options": [{"text": "微細", "is_correct": true, "explanation": "目に見えにくい細かいほこりなので「微細」。"}, {"text": "巨大", "is_correct": false, "explanation": "意味：巨大なほこりが空気中にあるのは不自然。"}, {"text": "有名", "is_correct": false, "explanation": "意味：ほこりが有名ということはない。"}, {"text": "丁寧", "is_correct": false, "explanation": "語域・意味：丁寧は人の態度に使い、ほこりには使わない。"}], "explanations": {"微細": "目に見えにくい細かいほこりなので「微細」。", "巨大": "意味：巨大なほこりが空気中にあるのは不自然。", "有名": "意味：ほこりが有名ということはない。", "丁寧": "語域・意味：丁寧は人の態度に使い、ほこりには使わない。"}, "sentence_index": 0, "correct_answer": "微細"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "微細な変化を気づいた。", "explanation": "助詞の誤り：「変化に気づく」とすべき。"}, {"text": "微細な変化に一匹気づいた。", "explanation": "助数詞の誤り：変化を「匹」で数えない。"}, {"text": "微細だ変化に気づいた。", "explanation": "活用の誤り：名詞を修飾するときは「微細な」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59aa89a-a9b4-4f65-80dc-a6bcb4d0dd78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36070, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この粉はとても微細の。", "corrected_sentence": "この粉はとても微細だ。", "error_description": "活用の誤り：な形容詞の述語は「だ」で終える。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "微細", "is_correct": true, "explanation": "「な」に続いて名詞「傷」を修飾する語幹。"}, {"text": "微細さ", "is_correct": false, "explanation": "名詞形で「な」に続かない。"}, {"text": "微細に", "is_correct": false, "explanation": "連用形で名詞を修飾できない。"}, {"text": "微細だ", "is_correct": false, "explanation": "終止形で「な」に続かない。"}], "correct_form": "微細", "base_form": "微細", "form_label": "語幹（連体形「な」の前）", "sentence_index": 1, "explanations": {"微細": "「な」に続いて名詞「傷」を修飾する語幹。", "微細さ": "名詞形で「な」に続かない。", "微細に": "連用形で名詞を修飾できない。", "微細だ": "終止形で「な」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59aa89a-a9b4-4f65-80dc-a6bcb4d0dd78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36070, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "巨大", "is_correct": true, "explanation": "とても大きいことで、微細の対義語。"}, {"text": "微小", "is_correct": false, "explanation": "非常に小さいことで、類義語であり対義語ではない。"}, {"text": "精密", "is_correct": false, "explanation": "細かく正確なことで、対義関係にない。"}, {"text": "繊細", "is_correct": false, "explanation": "細やかなことで、対義ではない。"}], "correct_answer": "巨大", "explanations": {"巨大": "とても大きいことで、微細の対義語。", "微小": "非常に小さいことで、類義語であり対義語ではない。", "精密": "細かく正確なことで、対義関係にない。", "繊細": "細やかなことで、対義ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59aa89a-a9b4-4f65-80dc-a6bcb4d0dd78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36070, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "微細", "is_correct": true, "explanation": "びさい。細かいこと。"}, {"text": "微罪", "is_correct": false, "explanation": "びざい。二拍目「さ」→「ざ」の清濁の違い。軽い罪。"}, {"text": "二歳", "is_correct": false, "explanation": "にさい。一拍目「び」→「に」の一モーラ差。"}, {"text": "鬼才", "is_correct": false, "explanation": "きさい。一拍目「び」→「き」の一モーラ差。すぐれた才能。"}], "explanations": {"微細": "びさい。細かいこと。", "微罪": "びざい。二拍目「さ」→「ざ」の清濁の違い。軽い罪。", "二歳": "にさい。一拍目「び」→「に」の一モーラ差。", "鬼才": "きさい。一拍目「び」→「き」の一モーラ差。すぐれた才能。"}, "sentence_index": null, "correct_answer": "微細"}, "level_3": {"options": [{"text": "微細", "is_correct": true, "explanation": "砂がとても細かく砕かれた様子なので「微細」。"}, {"text": "有名", "is_correct": false, "explanation": "意味：砂が有名に砕かれることはない。"}, {"text": "元気", "is_correct": false, "explanation": "意味：元気は人の状態で、砕き方ではない。"}, {"text": "親切", "is_correct": false, "explanation": "意味：親切は人の態度で、砕き方を表さない。"}], "explanations": {"微細": "砂がとても細かく砕かれた様子なので「微細」。", "有名": "意味：砂が有名に砕かれることはない。", "元気": "意味：元気は人の状態で、砕き方ではない。", "親切": "意味：親切は人の態度で、砕き方を表さない。"}, "sentence_index": 6, "correct_answer": "微細"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "微細な粒が水を浮いている。", "explanation": "助詞の誤り：「水に浮く」とすべき。"}, {"text": "微細な粒が三冊浮いている。", "explanation": "助数詞の誤り：粒を「冊」で数えない。"}, {"text": "微細だ粒が水に浮いている。", "explanation": "活用の誤り：名詞を修飾するときは「微細な」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59aa89a-a9b4-4f65-80dc-a6bcb4d0dd78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
