INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36072, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "長さや重さ、時間などをはかるときのもとになる量。", "primary_collocate": null, "pronunciation": "たんい", "ipa": "taɴi", "syllable_count": 3, "sentences": [{"text": "長さの単位はメートルです。", "target_word": "単位", "complexity_tier": "T3", "furigana": "なが たんい", "sentence_source": "generated"}, {"text": "重さを表す単位を覚えた。", "target_word": "単位", "complexity_tier": "T3", "furigana": "おも あらわ たんい おぼ", "sentence_source": "generated"}, {"text": "時間の単位には秒や分がある。", "target_word": "単位", "complexity_tier": "T3", "furigana": "じかん たんい びょう ふん", "sentence_source": "generated"}, {"text": "この単位の読み方がわからない。", "target_word": "単位", "complexity_tier": "T3", "furigana": "たんい よ かた", "sentence_source": "generated"}, {"text": "単位を書き忘れて点を引かれた。", "target_word": "単位", "complexity_tier": "T3", "furigana": "たんい か わす てん ひ", "sentence_source": "generated"}, {"text": "国によって使う単位が違う。", "target_word": "単位", "complexity_tier": "T3", "furigana": "くに つか たんい ちが", "sentence_source": "generated"}, {"text": "答えには必ず単位をつけてください。", "target_word": "単位", "complexity_tier": "T3", "furigana": "こた かなら たんい", "sentence_source": "generated"}, {"text": "グラムは重さの単位だ。", "target_word": "単位", "complexity_tier": "T3", "furigana": "おも たんい", "sentence_source": "generated"}, {"text": "先生が新しい単位を説明している。", "target_word": "単位", "complexity_tier": "T3", "furigana": "せんせい あたら たんい せつめい", "sentence_source": "generated"}, {"text": "単位が違うと比べられない。", "target_word": "単位", "complexity_tier": "T3", "furigana": "たんい ちが くら", "sentence_source": "generated"}], "morphological_forms": [{"form": "単位数", "label": "派生"}, {"form": "単位系", "label": "派生"}, {"form": "一単位", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | はかるときのもとになる量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'