INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35396, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが形となって作られること。", "primary_collocate": null, "pronunciation": "けいせい", "ipa": "keːseː", "syllable_count": 4, "sentences": [{"text": "性格の形成には家庭が大切だ。", "target_word": "形成", "complexity_tier": "T3", "furigana": "せいかく けいせい かてい たいせつ", "sentence_source": "generated"}, {"text": "山は長い時間をかけて形成された。", "target_word": "形成", "complexity_tier": "T3", "furigana": "やま なが じかん けいせい", "sentence_source": "generated"}, {"text": "友だちとの関係を形成していく。", "target_word": "形成", "complexity_tier": "T3", "furigana": "とも かんけい けいせい", "sentence_source": "generated"}, {"text": "雲の形成について調べた。", "target_word": "形成", "complexity_tier": "T3", "furigana": "くも けいせい しら", "sentence_source": "generated"}, {"text": "町の形成には川が関係している。", "target_word": "形成", "complexity_tier": "T3", "furigana": "まち けいせい かわ かんけい", "sentence_source": "generated"}, {"text": "チームの形成に時間がかかった。", "target_word": "形成", "complexity_tier": "T3", "furigana": "けいせい じかん", "sentence_source": "generated"}, {"text": "島が形成される様子を見た。", "target_word": "形成", "complexity_tier": "T3", "furigana": "しま けいせい ようす み", "sentence_source": "generated"}, {"text": "考え方の形成は子どもの時に始まる。", "target_word": "形成", "complexity_tier": "T3", "furigana": "かんが かた けいせい こ とき はじ", "sentence_source": "generated"}, {"text": "形成の過程を図で説明する。", "target_word": "形成", "complexity_tier": "T3", "furigana": "けいせい かてい ず せつめい", "sentence_source": "generated"}, {"text": "新しい町が形成されている。", "target_word": "形成", "complexity_tier": "T3", "furigana": "あたら まち けいせい", "sentence_source": "generated"}], "morphological_forms": [{"form": "形成する", "label": "派生"}, {"form": "形成される", "label": "活用"}, {"form": "人格形成", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 形となって作られること", "collocate_grounding": {"status": "no_source", "reason": "no collocat