INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35398, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物と物がくっついて、一つにつながること。", "primary_collocate": null, "pronunciation": "つながる", "ipa": "tsɯnaɡaɾɯ", "syllable_count": 4, "sentences": [{"text": "二つの部屋は廊下で繋がっている。", "target_word": "繋がって", "complexity_tier": "T3", "furigana": "ふた へや ろうか つな", "sentence_source": "generated"}, {"text": "この道は駅まで繋がっている。", "target_word": "繋がって", "complexity_tier": "T3", "furigana": "みち えき つな", "sentence_source": "generated"}, {"text": "ひもが切れずに繋がっていた。", "target_word": "繋がって", "complexity_tier": "T3", "furigana": "き つな", "sentence_source": "generated"}, {"text": "島と本土が橋で繋がった。", "target_word": "繋がった", "complexity_tier": "T3", "furigana": "しま ほんど はし つな", "sentence_source": "generated"}, {"text": "線が繋がらないと電気がつかない。", "target_word": "繋がらない", "complexity_tier": "T3", "furigana": "せん つな でんき", "sentence_source": "generated"}, {"text": "鎖の輪がしっかり繋がる。", "target_word": "繋がる", "complexity_tier": "T3", "furigana": "くさり わ つな", "sentence_source": "generated"}, {"text": "繋がった電車がゆっくり動く。", "target_word": "繋がった", "complexity_tier": "T3", "furigana": "つな でんしゃ うご", "sentence_source": "generated"}, {"text": "二本のパイプが繋がっている。", "target_word": "繋がって", "complexity_tier": "T3", "furigana": "にほん つな", "sentence_source": "generated"}, {"text": "この川は海に繋がっている。", "target_word": "繋がって", "complexity_tier": "T3", "furigana": "かわ うみ つな", "sentence_source": "generated"}, {"text": "トンネルで町と町が繋がる。", "target_word": "繋がる", "complexity_tier": "T3", "furigana": "まち まち つな", "sentence_source": "generated"}], "morphological_forms": [{"form": "繋がった", "label": "活用"}, {"form": "繋がって", "label": "活用"}, {"form": "繋がらない", "label": "活用"}, {"form": "繋がり", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 物と物がくっついて続く", "collocate_grounding": {"status": "no_source", "reason": "no colloca