INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35399, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人や物事の間に関係ができること。", "primary_collocate": null, "pronunciation": "つながる", "ipa": "tsɯnaɡaɾɯ", "syllable_count": 4, "sentences": [{"text": "小さなミスが事故に繋がった。", "target_word": "繋がった", "complexity_tier": "T3", "furigana": "ちい じこ つな", "sentence_source": "generated"}, {"text": "毎日の練習が自信に繋がる。", "target_word": "繋がる", "complexity_tier": "T3", "furigana": "まいにち れんしゅう じしん つな", "sentence_source": "generated"}, {"text": "ネットで世界の人と繋がれる。", "target_word": "繋がれる", "complexity_tier": "T3", "furigana": "せかい ひと つな", "sentence_source": "generated"}, {"text": "その話は前の話と繋がっている。", "target_word": "繋がって", "complexity_tier": "T3", "furigana": "はなし まえ はなし つな", "sentence_source": "generated"}, {"text": "努力が結果に繋がらなかった。", "target_word": "繋がらなかった", "complexity_tier": "T3", "furigana": "どりょく けっか つな", "sentence_source": "generated"}, {"text": "音楽で人と人が繋がる。", "target_word": "繋がる", "complexity_tier": "T3", "furigana": "おんがく ひと ひと つな", "sentence_source": "generated"}, {"text": "その出会いが仕事に繋がった。", "target_word": "繋がった", "complexity_tier": "T3", "furigana": "であ しごと つな", "sentence_source": "generated"}, {"text": "血の繋がった家族を大切にする。", "target_word": "繋がった", "complexity_tier": "T3", "furigana": "ち つな かぞく たいせつ", "sentence_source": "generated"}, {"text": "この経験は将来に繋がると思う。", "target_word": "繋がる", "complexity_tier": "T3", "furigana": "けいけん しょうらい つな おも", "sentence_source": "generated"}, {"text": "友だちと心が繋がっている。", "target_word": "繋がって", "complexity_tier": "T3", "furigana": "とも こころ つな", "sentence_source": "generated"}], "morphological_forms": [{"form": "繋がった", "label": "活用"}, {"form": "繋がって", "label": "活用"}, {"form": "繋がらない", "label": "活用"}, {"form": "繋がり", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 人や物事の間に関係ができる", "collocate_grounding": {"status": "n