INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35404, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "もののしくみや組み立て。", "primary_collocate": null, "pronunciation": "こうぞう", "ipa": "koːzoː", "syllable_count": 4, "sentences": [{"text": "この家の構造はとても強い。", "target_word": "構造", "complexity_tier": "T3", "furigana": "いえ こうぞう つよ", "sentence_source": "generated"}, {"text": "体の構造を理科で学んだ。", "target_word": "構造", "complexity_tier": "T3", "furigana": "からだ こうぞう りか まな", "sentence_source": "generated"}, {"text": "文の構造がわかると読みやすい。", "target_word": "構造", "complexity_tier": "T3", "furigana": "ぶん こうぞう よ", "sentence_source": "generated"}, {"text": "橋の構造を図で調べている。", "target_word": "構造", "complexity_tier": "T3", "furigana": "はし こうぞう ず しら", "sentence_source": "generated"}, {"text": "構造が複雑な機械を直した。", "target_word": "構造", "complexity_tier": "T3", "furigana": "こうぞう ふくざつ きかい なお", "sentence_source": "generated"}, {"text": "地球の内部の構造は面白い。", "target_word": "構造", "complexity_tier": "T3", "furigana": "ちきゅう ないぶ こうぞう おもしろ", "sentence_source": "generated"}, {"text": "会社の構造を変える必要がある。", "target_word": "構造", "complexity_tier": "T3", "furigana": "かいしゃ こうぞう か ひつよう", "sentence_source": "generated"}, {"text": "この時計は構造が簡単だ。", "target_word": "構造", "complexity_tier": "T3", "furigana": "とけい こうぞう かんたん", "sentence_source": "generated"}, {"text": "花の構造を観察してみよう。", "target_word": "構造", "complexity_tier": "T3", "furigana": "はな こうぞう かんさつ", "sentence_source": "generated"}, {"text": "建物の構造に問題が見つかった。", "target_word": "構造", "complexity_tier": "T3", "furigana": "たてもの こうぞう もんだい み", "sentence_source": "generated"}], "morphological_forms": [{"form": "構造的", "label": "派生"}, {"form": "構造上", "label": "派生"}, {"form": "社会構造", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | もののしくみや組み立て", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for