INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35412, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "形や様子が、前とはまったく別のものに変わること。", "primary_collocate": null, "pronunciation": "へんよう", "ipa": "heɲjoː", "syllable_count": 4, "sentences": [{"text": "町の変容に住民はおどろいた。", "target_word": "変容", "complexity_tier": "T3", "furigana": "まち へんよう じゅうみん", "sentence_source": "generated"}, {"text": "彼の考え方は大きく変容した。", "target_word": "変容", "complexity_tier": "T3", "furigana": "かれ かんが かた おお へんよう", "sentence_source": "generated"}, {"text": "社会の変容について話し合った。", "target_word": "変容", "complexity_tier": "T3", "furigana": "しゃかい へんよう はな あ", "sentence_source": "generated"}, {"text": "この十年で村は変容している。", "target_word": "変容", "complexity_tier": "T3", "furigana": "じゅうねん むら へんよう", "sentence_source": "generated"}, {"text": "変容した景色を写真にとった。", "target_word": "変容", "complexity_tier": "T3", "furigana": "へんよう けしき しゃしん", "sentence_source": "generated"}, {"text": "文化の変容はゆっくり進む。", "target_word": "変容", "complexity_tier": "T3", "furigana": "ぶんか へんよう すす", "sentence_source": "generated"}, {"text": "彼女の態度の変容に気づいた。", "target_word": "変容", "complexity_tier": "T3", "furigana": "かのじょ たいど へんよう き", "sentence_source": "generated"}, {"text": "変容の理由を考えてみよう。", "target_word": "変容", "complexity_tier": "T3", "furigana": "へんよう りゆう かんが", "sentence_source": "generated"}, {"text": "ネットは生活を変容させた。", "target_word": "変容", "complexity_tier": "T3", "furigana": "せいかつ へんよう", "sentence_source": "generated"}, {"text": "家族の形が変容している。", "target_word": "変容", "complexity_tier": "T3", "furigana": "かぞく かたち へんよう", "sentence_source": "generated"}], "morphological_forms": [{"form": "変容する", "label": "派生"}, {"form": "変容した", "label": "活用"}, {"form": "変容させる", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 様子がまったく別に変わること", "collocate_grounding": {"status": "no_source", "reason": "no collocate