INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36072, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "単位", "is_correct": true, "explanation": "音声は「たんい」で、これが正解の語。"}, {"text": "短気", "is_correct": false, "explanation": "「たんき」と読み、すぐ怒る性格という意味。最後の音が違う。"}, {"text": "担架", "is_correct": false, "explanation": "「たんか」と読み、けが人を運ぶ道具という意味。最後の音が違う。"}, {"text": "簡易", "is_correct": false, "explanation": "「かんい」と読み、手軽で簡単なことという意味。最初の音が違う。"}, {"text": "繊維", "is_correct": false, "explanation": "「せんい」と読み、糸のように細いものという意味。最初の音が違う。"}], "explanations": {"単位": "音声は「たんい」で、これが正解の語。", "短気": "「たんき」と読み、すぐ怒る性格という意味。最後の音が違う。", "担架": "「たんか」と読み、けが人を運ぶ道具という意味。最後の音が違う。", "簡易": "「かんい」と読み、手軽で簡単なことという意味。最初の音が違う。", "繊維": "「せんい」と読み、糸のように細いものという意味。最初の音が違う。"}, "sentence_index": null, "correct_answer": "単位"}, "level_3": {"options": [{"text": "単位", "is_correct": true, "explanation": "長さをはかるもとになる量なので正しい。"}, {"text": "値段", "is_correct": false, "explanation": "メートルは値段ではないので意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "長さの天気という言い方はない。"}, {"text": "気持ち", "is_correct": false, "explanation": "長さの気持ちは意味が通らない。"}], "explanations": {"単位": "長さをはかるもとになる量なので正しい。", "値段": "メートルは値段ではないので意味が合わない。", "天気": "長さの天気という言い方はない。", "気持ち": "長さの気持ちは意味が通らない。"}, "sentence_index": 0, "correct_answer": "単位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この単位が読み方をわからない。", "explanation": "「が」と「を」の使い方が誤り。正しくは「この単位の読み方がわからない」。"}, {"text": "単位を三匹覚えた。", "explanation": "単位を数えるのに「匹」は使わない。「三つ」が正しい。"}, {"text": "わからない読み方がこの単位の。", "explanation": "語の順番がこわれていて文になっていない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be34177-8189-49f2-8f84-fa59299de64d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
