INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36072, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「単位を覚える」で、覚える対象を表す「を」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「単位が覚えた」では単位が覚えたことになる。"}, {"text": "に", "is_correct": false, "explanation": "「単位に覚えた」は動作の相手を表し、合わない。"}, {"text": "で", "is_correct": false, "explanation": "「単位で覚えた」は手段を表し、意味が変わる。"}], "correct_answer": "を", "explanations": {"を": "「単位を覚える」で、覚える対象を表す「を」が正しい。", "が": "「単位が覚えた」では単位が覚えたことになる。", "に": "「単位に覚えた」は動作の相手を表し、合わない。", "で": "「単位で覚えた」は手段を表し、意味が変わる。"}, "error_tags": {"が": "subject_object", "に": "target", "で": "means"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be34177-8189-49f2-8f84-fa59299de64d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36072, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "単位", "is_correct": true, "explanation": "音声は「たんい」で、これが正解の語。"}, {"text": "退位", "is_correct": false, "explanation": "「たいい」と読み、王が位をしりぞくことという意味。「ん」と「い」が違う。"}, {"text": "善意", "is_correct": false, "explanation": "「ぜんい」と読み、よい心という意味。「た」と「ぜ」が違う。"}, {"text": "権威", "is_correct": false, "explanation": "「けんい」と読み、人を従わせる力という意味。「た」と「け」が違う。"}, {"text": "難易", "is_correct": false, "explanation": "「なんい」と読み、むずかしさとやさしさという意味。「た」と「な」が違う。"}], "explanations": {"単位": "音声は「たんい」で、これが正解の語。", "退位": "「たいい」と読み、王が位をしりぞくことという意味。「ん」と「い」が違う。", "善意": "「ぜんい」と読み、よい心という意味。「た」と「ぜ」が違う。", "権威": "「けんい」と読み、人を従わせる力という意味。「た」と「け」が違う。", "難易": "「なんい」と読み、むずかしさとやさしさという意味。「た」と「な」が違う。"}, "sentence_index": null, "correct_answer": "単位"}, "level_3": {"options": [{"text": "単位", "is_correct": true, "explanation": "答えに「cm」などをつけるのは単位なので正しい。"}, {"text": "傘", "is_correct": false, "explanation": "答えに傘をつけるは意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "答えに天気をつけるは意味が合わない。"}, {"text": "色", "is_correct": false, "explanation": "答えに色をつけるは意味が合わない。"}], "explanations": {"単位": "答えに「cm」などをつけるのは単位なので正しい。", "傘": "答えに傘をつけるは意味が通らない。", "天気": "答えに天気をつけるは意味が合わない。", "色": "答えに色をつけるは意味が合わない。"}, "sentence_index": 6, "correct_answer": "単位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "単位を違うと比べられない。", "explanation": "「を」ではなく「が」を使う。"}, {"text": "単位が違ったと比べられない。", "explanation": "「と」の前は「違う」の形にする。"}, {"text": "比べられない単位が違うと。", "explanation": "語の順番が誤っている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be34177-8189-49f2-8f84-fa59299de64d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_e