INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35396, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "形成", "is_correct": true, "explanation": "音声は「けいせい」で、これが正解の語。"}, {"text": "快晴", "is_correct": false, "explanation": "「かいせい」と読み、よく晴れた天気という意味。はじめの「け」が違う。"}, {"text": "名声", "is_correct": false, "explanation": "「めいせい」と読み、よい評判という意味。はじめの「け」が違う。"}, {"text": "形跡", "is_correct": false, "explanation": "「けいせき」と読み、何かがあったあとという意味。最後の「い」が違う。"}, {"text": "掲載", "is_correct": false, "explanation": "「けいさい」と読み、新聞などにのせることという意味。三番目の音が違う。"}], "explanations": {"形成": "音声は「けいせい」で、これが正解の語。", "快晴": "「かいせい」と読み、よく晴れた天気という意味。はじめの「け」が違う。", "名声": "「めいせい」と読み、よい評判という意味。はじめの「け」が違う。", "形跡": "「けいせき」と読み、何かがあったあとという意味。最後の「い」が違う。", "掲載": "「けいさい」と読み、新聞などにのせることという意味。三番目の音が違う。"}, "sentence_index": null, "correct_answer": "形成"}, "level_3": {"options": [{"text": "形成", "is_correct": true, "explanation": "性格が作られていくことなので正しい。"}, {"text": "計算", "is_correct": false, "explanation": "性格の計算という言い方はしない。"}, {"text": "掃除", "is_correct": false, "explanation": "性格の掃除は意味が通らない。"}, {"text": "出発", "is_correct": false, "explanation": "性格の出発は意味が合わない。"}], "explanations": {"形成": "性格が作られていくことなので正しい。", "計算": "性格の計算という言い方はしない。", "掃除": "性格の掃除は意味が通らない。", "出発": "性格の出発は意味が合わない。"}, "sentence_index": 0, "correct_answer": "形成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雲を形成について調べた。", "explanation": "「を」ではなく「の」を使う。"}, {"text": "雲の形成について調べている前だ。", "explanation": "時の表し方が誤っている。"}, {"text": "調べた雲の形成について。", "explanation": "語の順番がこわれている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be34177-8189-49f2-8f84-fa59299de64d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warning