INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35396, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "性格の形成には家庭を大切だ。", "corrected_sentence": "性格の形成には家庭が大切だ。", "error_description": "「大切だ」の主語は「が」で表す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be34177-8189-49f2-8f84-fa59299de64d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35396, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「時間をかける」で、かける対象を表す「を」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「時間がかけて」は文法的に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「時間にかけて」は意味が変わる。"}, {"text": "で", "is_correct": false, "explanation": "「時間でかけて」は自然でない。"}], "correct_answer": "を", "explanations": {"を": "「時間をかける」で、かける対象を表す「を」が正しい。", "が": "「時間がかけて」は文法的に合わない。", "に": "「時間にかけて」は意味が変わる。", "で": "「時間でかけて」は自然でない。"}, "error_tags": {"が": "subject_object", "に": "target", "で": "means"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "崩壊", "is_correct": true, "explanation": "形ができる「形成」と反対に、形がくずれることなので対義語。"}, {"text": "発展", "is_correct": false, "explanation": "発展は大きくなることで、反対の意味ではない。"}, {"text": "変化", "is_correct": false, "explanation": "変化はかわることで、形成の反対ではない。"}, {"text": "成長", "is_correct": false, "explanation": "成長は育つことで、むしろ近い意味。"}], "correct_answer": "崩壊", "explanations": {"崩壊": "形ができる「形成」と反対に、形がくずれることなので対義語。", "発展": "発展は大きくなることで、反対の意味ではない。", "変化": "変化はかわることで、形成の反対ではない。", "成長": "成長は育つことで、むしろ近い意味。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be34177-8189-49f2-8f84-fa59299de64d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35396, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "形成", "is_correct": true, "explanation": "音声は「けいせい」で、これが正解の語。"}, {"text": "体制", "is_correct": false, "explanation": "「たいせい」と読み、社会や組織のしくみという意味。「け」と「た」が違う。"}, {"text": "訂正", "is_correct": false, "explanation": "「ていせい」と読み、まちがいを直すことという意味。「け」と「て」が違う。"}, {"text": "経線", "is_correct": false, "explanation": "「けいせん」と読み、地図のたての線という意味。最後の「い」と「ん」が違う。"}], "explanations": {"形成": "音声は「けいせい」で、これが正解の語。", "体制": "「たいせい」と読み、社会や組織のしくみという意味。「け」と「た」が違う。", "訂正": "「ていせい」と読み、まちがいを直すことという意味。「け」と「て」が違う。", "経線": "「けいせん」と読み、地図のたての線という意味。最後の「い」と「ん」が違う。"}, "sentence_index": null, "correct_answer": "形成"}, "level_3": {"options": [{"text": "形成", "is_correct": true, "explanation": "島ができて形になることなので正しい。"}, {"text": "見学", "is_correct": false, "explanation": "島が見学されるでは意味が合わない。"}, {"text": "注文", "is_correct": false, "explanation": "島が注文されるは不自然。"}, {"text": "返事", "is_correct": false, "explanation": "島が返事されるは意味が通らない。"}], "explanations": {"形成": "島ができて形になることなので正しい。", "見学": "島が見学されるでは意味が合わない。", "注文": "島が注文されるは不自然。", "返事": "島が返事されるは意味が通らない。"}, "sentence_index": 6, "correct_answer": "形成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しい町を形成されている。", "explanation": "受身の文なので「を」ではなく「が」を使う。"}, {"text": "新しい町が形成されてある。", "explanation": "「されてある」は誤り。「されている」が正しい。"}, {"text": "形成されている新しい町が。", "explanation": "語の順番が誤っていて文が終わらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be34177-8189-49f2-8f84-fa59299de64d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35396, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "考え方の形成に子どもの時に始まる。", "corrected_sentence": "考え方の形成は子どもの時に始まる。", "error_description": "主題は「に」ではなく「は」で示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be34177-8189-49f2-8f84-fa59299de64d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35396, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「考え方の形成」を話題として示す「は」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「形成を始まる」は自動詞と合わない。"}, {"text": "で", "is_correct": false, "explanation": "「形成で始まる」は意味が変わる。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し合わない。"}], "correct_answer": "は", "explanations": {"は": "「考え方の形成」を話題として示す「は」が正しい。", "を": "「形成を始まる」は自動詞と合わない。", "で": "「形成で始まる」は意味が変わる。", "へ": "「へ」は方向を表し合わない。"}, "error_tags": {"を": "subject_object", "で": "means", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "崩壊", "is_correct": true, "explanation": "作られた形がくずれることで、形成の反対。"}, {"text": "完成", "is_correct": false, "explanation": "完成はでき上がることで、反対ではない。"}, {"text": "拡大", "is_correct": false, "explanation": "拡大は大きくすることで、反対ではない。"}, {"text": "誕生", "is_correct": false, "explanation": "誕生は生まれることで、近い意味になる。"}], "correct_answer": "崩壊", "explanations": {"崩壊": "作られた形がくずれることで、形成の反対。", "完成": "完成はでき上がることで、反対ではない。", "拡大": "拡大は大きくすることで、反対ではない。", "誕生": "誕生は生まれることで、近い意味になる。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be34177-8189-49f2-8f84-fa59299de64d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35398, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "繋がる", "is_correct": true, "explanation": "音声は「つながる」で、これが正解の語。"}, {"text": "強がる", "is_correct": false, "explanation": "「つよがる」と読み、強いふりをするという意味。二番目の音が違う。"}, {"text": "繋げる", "is_correct": false, "explanation": "「つなげる」と読み、物と物をつなぐという意味。三番目の音が違う。"}, {"text": "辛がる", "is_correct": false, "explanation": "「つらがる」と読み、つらそうにするという意味。二番目の音が違う。"}], "explanations": {"繋がる": "音声は「つながる」で、これが正解の語。", "強がる": "「つよがる」と読み、強いふりをするという意味。二番目の音が違う。", "繋げる": "「つなげる」と読み、物と物をつなぐという意味。三番目の音が違う。", "辛がる": "「つらがる」と読み、つらそうにするという意味。二番目の音が違う。"}, "sentence_index": null, "correct_answer": "繋がる"}, "level_3": {"options": [{"text": "繋がって", "is_correct": true, "explanation": "二つの部屋が廊下でくっついていることなので正しい。"}, {"text": "並んで", "is_correct": false, "explanation": "並んでいるだけでは「廊下で」と合わない。"}, {"text": "笑って", "is_correct": false, "explanation": "部屋が廊下で笑っているは意味が通らない。"}, {"text": "壊れて", "is_correct": false, "explanation": "部屋が廊下で壊れているは意味が通らない。"}], "explanations": {"繋がって": "二つの部屋が廊下でくっついていることなので正しい。", "並んで": "並んでいるだけでは「廊下で」と合わない。", "笑って": "部屋が廊下で笑っているは意味が通らない。", "壊れて": "部屋が廊下で壊れているは意味が通らない。"}, "sentence_index": 0, "correct_answer": "繋がって"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "島と本土を橋で繋がった。", "explanation": "「繋がる」は自動詞なので「を」ではなく「が」。"}, {"text": "島と本土が橋に繋がった。", "explanation": "手段を表すのは「に」ではなく「で」。"}, {"text": "繋がった島と本土が橋で明日。", "explanation": "語の順番と時の表し方が誤っている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be34177-8189-49f2-8f84-fa59299de64d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35398, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この道を駅まで繋がっている。", "corrected_sentence": "この道は駅まで繋がっている。", "error_description": "自動詞「繋がる」には「を」を使わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "繋がって", "is_correct": true, "explanation": "「ている」に続くのはて形。"}, {"text": "繋がった", "is_correct": false, "explanation": "「繋がったいる」とは言えない。"}, {"text": "繋がる", "is_correct": false, "explanation": "「繋がるいる」とは言えない。"}, {"text": "繋がらない", "is_correct": false, "explanation": "「繋がらないいる」は文法的に誤り。"}], "correct_form": "繋がって", "base_form": "繋がる", "form_label": "て形（ている）", "sentence_index": 1, "explanations": {"繋がって": "「ている」に続くのはて形。", "繋がった": "「繋がったいる」とは言えない。", "繋がる": "「繋がるいる」とは言えない。", "繋がらない": "「繋がらないいる」は文法的に誤り。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be34177-8189-49f2-8f84-fa59299de64d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35398, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "まで", "options": [{"text": "まで", "is_correct": true, "explanation": "道が駅に届く終点を表す「まで」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "自動詞「繋がる」に「を」は使わない。"}, {"text": "で", "is_correct": false, "explanation": "「駅で」は場所を表し、道の終点にならない。"}, {"text": "が", "is_correct": false, "explanation": "「駅が繋がっている」では道との関係が表せない。"}], "correct_answer": "まで", "explanations": {"まで": "道が駅に届く終点を表す「まで」が正しい。", "を": "自動詞「繋がる」に「を」は使わない。", "で": "「駅で」は場所を表し、道の終点にならない。", "が": "「駅が繋がっている」では道との関係が表せない。"}, "error_tags": {"を": "subject_object", "で": "location", "が": "subject_object"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "切れる", "is_correct": true, "explanation": "くっついていたものが離れることで、繋がるの反対。"}, {"text": "結ぶ", "is_correct": false, "explanation": "結ぶはつなぐことで、反対ではない。"}, {"text": "届く", "is_correct": false, "explanation": "届くは先までつくことで、反対ではない。"}, {"text": "渡る", "is_correct": false, "explanation": "渡るは橋などをこえることで、反対ではない。"}], "correct_answer": "切れる", "explanations": {"切れる": "くっついていたものが離れることで、繋がるの反対。", "結ぶ": "結ぶはつなぐことで、反対ではない。", "届く": "届くは先までつくことで、反対ではない。", "渡る": "渡るは橋などをこえることで、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be34177-8189-49f2-8f84-fa59299de64d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35398, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "繋がる", "is_correct": true, "explanation": "音声は「つながる」で、これが正解の語。"}, {"text": "強がる", "is_correct": false, "explanation": "「つよがる」と読み、強いふりをするという意味。「な」と「よ」が違う。"}, {"text": "連なる", "is_correct": false, "explanation": "「つらなる」と読み、並んで続くという意味。「な」と「ら」、「が」と「な」が違う。"}, {"text": "捕まる", "is_correct": false, "explanation": "「つかまる」と読み、とらえられるという意味。「な」と「か」、「が」と「ま」が違う。"}], "explanations": {"繋がる": "音声は「つながる」で、これが正解の語。", "強がる": "「つよがる」と読み、強いふりをするという意味。「な」と「よ」が違う。", "連なる": "「つらなる」と読み、並んで続くという意味。「な」と「ら」、「が」と「な」が違う。", "捕まる": "「つかまる」と読み、とらえられるという意味。「な」と「か」、「が」と「ま」が違う。"}, "sentence_index": null, "correct_answer": "繋がる"}, "level_3": {"options": [{"text": "繋がった", "is_correct": true, "explanation": "車両がつながった状態の電車なので正しい。"}, {"text": "眠った", "is_correct": false, "explanation": "電車が眠ったは意味が通らない。"}, {"text": "消えた", "is_correct": false, "explanation": "消えた電車が動くは意味が通らない。"}, {"text": "割れた", "is_correct": false, "explanation": "割れた電車は意味が合わない。"}], "explanations": {"繋がった": "車両がつながった状態の電車なので正しい。", "眠った": "電車が眠ったは意味が通らない。", "消えた": "消えた電車が動くは意味が通らない。", "割れた": "割れた電車は意味が合わない。"}, "sentence_index": 6, "correct_answer": "繋がった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "トンネルで町と町を繋がる。", "explanation": "自動詞なので「を」ではなく「が」。"}, {"text": "トンネルに町と町が繋がる。", "explanation": "手段は「に」ではなく「で」で表す。"}, {"text": "町と町が繋がるトンネルで昨日。", "explanation": "語の順番と時の位置が誤っている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be34177-8189-49f2-8f84-fa59299de64d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUD