INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35398, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二本のパイプを繋がっている。", "corrected_sentence": "二本のパイプが繋がっている。", "error_description": "自動詞「繋がる」の主語は「が」で表す。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "繋がって", "is_correct": true, "explanation": "「いる」の前にはて形が来る。"}, {"text": "繋がれば", "is_correct": false, "explanation": "条件形は「いる」に続かない。"}, {"text": "繋がろう", "is_correct": false, "explanation": "意向形は「いる」に続かない。"}, {"text": "繋がります", "is_correct": false, "explanation": "ます形は「いる」の前に置けない。"}], "correct_form": "繋がって", "base_form": "繋がる", "form_label": "て形（ている）", "sentence_index": 7, "explanations": {"繋がって": "「いる」の前にはて形が来る。", "繋がれば": "条件形は「いる」に続かない。", "繋がろう": "意向形は「いる」に続かない。", "繋がります": "ます形は「いる」の前に置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be34177-8189-49f2-8f84-fa59299de64d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
