INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35399, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "繋がる", "is_correct": true, "explanation": "音声は「つながる」で、これが正解の語。"}, {"text": "強がる", "is_correct": false, "explanation": "「つよがる」と読み、強いふりをするという意味。「な」と「よ」が違う。"}, {"text": "繋げる", "is_correct": false, "explanation": "「つなげる」と読み、関係をつくる（他動詞）という意味。「が」と「げ」が違う。"}, {"text": "辛がる", "is_correct": false, "explanation": "「つらがる」と読み、つらそうにするという意味。「な」と「ら」が違う。"}], "explanations": {"繋がる": "音声は「つながる」で、これが正解の語。", "強がる": "「つよがる」と読み、強いふりをするという意味。「な」と「よ」が違う。", "繋げる": "「つなげる」と読み、関係をつくる（他動詞）という意味。「が」と「げ」が違う。", "辛がる": "「つらがる」と読み、つらそうにするという意味。「な」と「ら」が違う。"}, "sentence_index": null, "correct_answer": "繋がる"}, "level_3": {"options": [{"text": "繋がった", "is_correct": true, "explanation": "小さなミスが事故という結果になったので正しい。"}, {"text": "喜んだ", "is_correct": false, "explanation": "ミスが事故に喜んだは意味が通らない。"}, {"text": "勝った", "is_correct": false, "explanation": "ミスが事故に勝ったは意味が合わない。"}, {"text": "答えた", "is_correct": false, "explanation": "ミスが事故に答えたは不自然。"}], "explanations": {"繋がった": "小さなミスが事故という結果になったので正しい。", "喜んだ": "ミスが事故に喜んだは意味が通らない。", "勝った": "ミスが事故に勝ったは意味が合わない。", "答えた": "ミスが事故に答えたは不自然。"}, "sentence_index": 0, "correct_answer": "繋がった"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その話を前の話と繋がっている。", "explanation": "「を」ではなく「は」を使う。"}, {"text": "その話は前の話と繋がってある。", "explanation": "「てある」は自動詞に使えない。"}, {"text": "前の話と繋がっているその話は。", "explanation": "語の順番が誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be34177-8189-49f2-8f84-fa59299de64d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation