INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35414, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「引き起こす」の目的語を表す。"}, {"text": "が", "is_correct": false, "explanation": "主格の「が」は他動詞の目的語には使えない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を表し、ここでは不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "他動詞「引き起こす」の目的語を表す。", "が": "主格の「が」は他動詞の目的語には使えない。", "で": "手段・場所を表し、ここでは不自然。", "へ": "方向を表し、目的語にならない。"}, "error_tags": {"が": "object_marking", "で": "instrument", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "防ぐ", "is_correct": true, "explanation": "悪い事態が起きないようにすることで、引き起こすと反対。"}, {"text": "招く", "is_correct": false, "explanation": "悪い結果を生む意味で、類義に近い。"}, {"text": "生む", "is_correct": false, "explanation": "結果を生じさせる意味で、対義ではない。"}, {"text": "起こす", "is_correct": false, "explanation": "ほぼ同じ意味で、対義ではない。"}], "correct_answer": "防ぐ", "explanations": {"防ぐ": "悪い事態が起きないようにすることで、引き起こすと反対。", "招く": "悪い結果を生む意味で、類義に近い。", "生む": "結果を生じさせる意味で、対義ではない。", "起こす": "ほぼ同じ意味で、対義ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdf10d2b-cf29-4178-a17c-73cb01d233de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
