INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35424, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地面の下にある、かたい岩の部分。", "primary_collocate": null, "pronunciation": "ちかく", "ipa": "tɕikakɯ", "syllable_count": 3, "sentences": [{"text": "地殻はかたい岩でできている。", "target_word": "地殻", "complexity_tier": "T3", "furigana": "ちかく", "sentence_source": "generated"}, {"text": "地殻の下にはマントルがある。", "target_word": "地殻", "complexity_tier": "T3", "furigana": "ちかく", "sentence_source": "generated"}, {"text": "地殻が少しずつ動いている。", "target_word": "地殻", "complexity_tier": "T3", "furigana": "ちかく", "sentence_source": "generated"}, {"text": "先生が地殻について話した。", "target_word": "地殻", "complexity_tier": "T3", "furigana": "ちかく", "sentence_source": "generated"}, {"text": "地震は地殻の動きで起こる。", "target_word": "地殻", "complexity_tier": "T3", "furigana": "ちかく", "sentence_source": "generated"}, {"text": "地殻を調べる研究をしたい。", "target_word": "地殻", "complexity_tier": "T3", "furigana": "ちかく", "sentence_source": "generated"}, {"text": "海の下の地殻はうすい。", "target_word": "地殻", "complexity_tier": "T3", "furigana": "ちかく", "sentence_source": "generated"}, {"text": "地殻の厚さは場所でちがう。", "target_word": "地殻", "complexity_tier": "T3", "furigana": "ちかく", "sentence_source": "generated"}, {"text": "理科で地殻の図をかいた。", "target_word": "地殻", "complexity_tier": "T3", "furigana": "ちかく", "sentence_source": "generated"}, {"text": "山は地殻が押されてできた。", "target_word": "地殻", "complexity_tier": "T3", "furigana": "ちかく", "sentence_source": "generated"}], "morphological_forms": [{"form": "地殻変動", "label": "派生"}, {"form": "大陸地殻", "label": "派生"}, {"form": "海洋地殻", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 地面の下のかたい岩の部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '606960e3-f41e-4858-9b37-0f43c4c