INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35425, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地球の表面をおおう、かたい岩石の層。", "primary_collocate": null, "pronunciation": "ちかく", "ipa": "tɕikakɯ", "syllable_count": 3, "sentences": [{"text": "地殻は地球の表面をおおう層だ。", "target_word": "地殻", "complexity_tier": "T3", "furigana": "ちかく", "sentence_source": "generated"}, {"text": "地殻の動きで山ができる。", "target_word": "地殻", "complexity_tier": "T3", "furigana": "ちかく", "sentence_source": "generated"}, {"text": "大陸の地殻は厚い。", "target_word": "地殻", "complexity_tier": "T3", "furigana": "ちかく", "sentence_source": "generated"}, {"text": "地殻が動くと地震が起こる。", "target_word": "地殻", "complexity_tier": "T3", "furigana": "ちかく", "sentence_source": "generated"}, {"text": "科学者は地殻を調べている。", "target_word": "地殻", "complexity_tier": "T3", "furigana": "ちかく", "sentence_source": "generated"}, {"text": "地殻の下は熱いマントルだ。", "target_word": "地殻", "complexity_tier": "T3", "furigana": "ちかく", "sentence_source": "generated"}, {"text": "地殻には多くの岩石がある。", "target_word": "地殻", "complexity_tier": "T3", "furigana": "ちかく", "sentence_source": "generated"}, {"text": "火山は地殻のさけ目にできる。", "target_word": "地殻", "complexity_tier": "T3", "furigana": "ちかく", "sentence_source": "generated"}, {"text": "地殻の変化を学んでいる。", "target_word": "地殻", "complexity_tier": "T3", "furigana": "ちかく", "sentence_source": "generated"}, {"text": "海の地殻は大陸よりうすい。", "target_word": "地殻", "complexity_tier": "T3", "furigana": "ちかく", "sentence_source": "generated"}], "morphological_forms": [{"form": "地殻変動", "label": "派生"}, {"form": "大陸地殻", "label": "派生"}, {"form": "海洋地殻", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 地球表面をおおう岩石の層", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '606960e3-f41e-4858-9b37-0f43c4c