INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35888, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "音の高さが少ないようす。", "primary_collocate": "声", "pronunciation": "ひくい", "ipa": "çikɯi", "syllable_count": 3, "sentences": [{"text": "父は声が低い。", "target_word": "低い", "complexity_tier": "T3", "furigana": "ひくい", "sentence_source": "generated"}, {"text": "低い声で話してください。", "target_word": "低い", "complexity_tier": "T3", "furigana": "ひくい", "sentence_source": "generated"}, {"text": "この楽器の音は低い。", "target_word": "低い", "complexity_tier": "T3", "furigana": "ひくい", "sentence_source": "generated"}, {"text": "彼の低い声が好きだ。", "target_word": "低い", "complexity_tier": "T3", "furigana": "ひくい", "sentence_source": "generated"}, {"text": "低い音が遠くから聞こえる。", "target_word": "低い", "complexity_tier": "T3", "furigana": "ひくい", "sentence_source": "generated"}, {"text": "ピアノの左側は低い音が出る。", "target_word": "低い", "complexity_tier": "T3", "furigana": "ひくい", "sentence_source": "generated"}, {"text": "兄の歌う声は低い。", "target_word": "低い", "complexity_tier": "T3", "furigana": "ひくい", "sentence_source": "generated"}, {"text": "低い声だと聞きにくい。", "target_word": "低い", "complexity_tier": "T3", "furigana": "ひくい", "sentence_source": "generated"}, {"text": "この曲は低い音から始まる。", "target_word": "低い", "complexity_tier": "T3", "furigana": "ひくい", "sentence_source": "generated"}, {"text": "先生は低い声で笑った。", "target_word": "低い", "complexity_tier": "T3", "furigana": "ひくい", "sentence_source": "generated"}], "morphological_forms": [{"form": "低かった", "label": "活用"}, {"form": "低くて", "label": "活用"}, {"form": "低くない", "label": "活用"}, {"form": "低さ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形容詞 | 音の高さが少ないようす", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60696