INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35906, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "歩くこと。また、物事が進むこと。", "primary_collocate": null, "pronunciation": "あゆみ", "ipa": "ajɯmi", "syllable_count": 3, "sentences": [{"text": "赤ちゃんの歩みはゆっくりだ。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "あゆみ", "sentence_source": "generated"}, {"text": "祖父は歩みを止めて休んだ。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "あゆみ", "sentence_source": "generated"}, {"text": "彼女の歩みは速い。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "あゆみ", "sentence_source": "generated"}, {"text": "一歩ずつ歩みを進める。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "あゆみ", "sentence_source": "generated"}, {"text": "犬は歩みをゆるめた。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "あゆみ", "sentence_source": "generated"}, {"text": "工事の歩みがおそい。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "あゆみ", "sentence_source": "generated"}, {"text": "つかれて歩みが重くなった。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "あゆみ", "sentence_source": "generated"}, {"text": "町の歩みを本で学んだ。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "あゆみ", "sentence_source": "generated"}, {"text": "私たちは歩みをそろえた。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "あゆみ", "sentence_source": "generated"}, {"text": "研究の歩みは止まらない。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "あゆみ", "sentence_source": "generated"}], "morphological_forms": [{"form": "歩む", "label": "派生"}, {"form": "歩み寄る", "label": "派生"}, {"form": "歩み出す", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 歩くこと・進んでいくこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '606960e3-f41e-4858-9b37-0f43c4c5792c') ON CONFLIC