INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35907, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が歩くこと。また、物事が進んでいくこと。", "primary_collocate": null, "pronunciation": "あゆみ", "ipa": "ajɯmi", "syllable_count": 3, "sentences": [{"text": "この会社の歩みを紹介します。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "あゆみ", "sentence_source": "generated"}, {"text": "人類の歩みを学ぶ。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "あゆみ", "sentence_source": "generated"}, {"text": "老人の歩みはゆっくりだ。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "あゆみ", "sentence_source": "generated"}, {"text": "学校の百年の歩みを調べた。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "あゆみ", "sentence_source": "generated"}, {"text": "彼は静かに歩みを進めた。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "あゆみ", "sentence_source": "generated"}, {"text": "科学の歩みはとても速い。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "あゆみ", "sentence_source": "generated"}, {"text": "歩みを止めずに練習を続けた。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "あゆみ", "sentence_source": "generated"}, {"text": "町の歩みが写真でわかる。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "あゆみ", "sentence_source": "generated"}, {"text": "平和への歩みは長い。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "あゆみ", "sentence_source": "generated"}, {"text": "私たちの歩みは始まったばかりだ。", "target_word": "歩み", "complexity_tier": "T3", "furigana": "あゆみ", "sentence_source": "generated"}], "morphological_forms": [{"form": "歩む", "label": "派生"}, {"form": "歩み寄る", "label": "派生"}, {"form": "歩み出す", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 歩くことや物事の進み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '606960e3-f41e-4858-9b37-0f43c4c5792c'