INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36091, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "バロック", "is_correct": true, "explanation": "正解。「バロック」（ばろっく）です。"}, {"text": "ブロック", "is_correct": false, "explanation": "「ブロック」（ぶろっく）は一拍ちがう別の語です。"}, {"text": "バラック", "is_correct": false, "explanation": "「バラック」（ばらっく）は一拍ちがう別の語です。"}, {"text": "クロック", "is_correct": false, "explanation": "「クロック」（くろっく）は一拍ちがう別の語です。"}, {"text": "フロック", "is_correct": false, "explanation": "「フロック」（ふろっく）は一拍ちがう別の語です。"}], "explanations": {"バロック": "正解。「バロック」（ばろっく）です。", "ブロック": "「ブロック」（ぶろっく）は一拍ちがう別の語です。", "バラック": "「バラック」（ばらっく）は一拍ちがう別の語です。", "クロック": "「クロック」（くろっく）は一拍ちがう別の語です。", "フロック": "「フロック」（ふろっく）は一拍ちがう別の語です。"}, "sentence_index": null, "correct_answer": "バロック"}, "level_3": {"options": [{"text": "バロック", "is_correct": true, "explanation": "十七〜十八世紀の音楽の様式なので文に合います。"}, {"text": "ブロック", "is_correct": false, "explanation": "積み木などのかたまりで、音楽の種類ではありません。"}, {"text": "ポケット", "is_correct": false, "explanation": "服の物入れで、音楽とは関係ありません。"}, {"text": "ロケット", "is_correct": false, "explanation": "空を飛ぶ乗り物で、音楽の種類ではありません。"}], "explanations": {"バロック": "十七〜十八世紀の音楽の様式なので文に合います。", "ブロック": "積み木などのかたまりで、音楽の種類ではありません。", "ポケット": "服の物入れで、音楽とは関係ありません。", "ロケット": "空を飛ぶ乗り物で、音楽の種類ではありません。"}, "sentence_index": 0, "correct_answer": "バロック"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "バロックで手を洗った。", "explanation": "バロックは芸術の様式で、手を洗う道具ではありません。"}, {"text": "朝ごはんにバロックを食べた。", "explanation": "バロックは食べ物ではありません。"}, {"text": "雨がバロックに降っている。", "explanation": "バロックは天気や場所を表す語ではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e818d64-970d-4865-aea3-54e56193876e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUD