INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35425, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "原因・手段を表す「で」が正しいです。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を表し、ここでは非文です。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、原因になりません。"}, {"text": "に", "is_correct": false, "explanation": "「に」は着点を表し、「動きに山ができる」は非文です。"}], "correct_answer": "で", "explanations": {"で": "原因・手段を表す「で」が正しいです。", "を": "「を」は目的語を表し、ここでは非文です。", "へ": "「へ」は方向を表し、原因になりません。", "に": "「に」は着点を表し、「動きに山ができる」は非文です。"}, "error_tags": {"を": "object_marking", "へ": "direction", "に": "location_vs_target"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e818d64-970d-4865-aea3-54e56193876e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35425, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "地殻", "is_correct": true, "explanation": "正解。「地殻」（ちかく）です。"}, {"text": "遅刻", "is_correct": false, "explanation": "「遅刻」（ちこく）は一拍ちがう別の語です。"}, {"text": "力", "is_correct": false, "explanation": "「力」（ちから）は一拍ちがう別の語です。"}, {"text": "四角", "is_correct": false, "explanation": "「四角」（しかく）は一拍ちがう別の語です。"}], "explanations": {"地殻": "正解。「地殻」（ちかく）です。", "遅刻": "「遅刻」（ちこく）は一拍ちがう別の語です。", "力": "「力」（ちから）は一拍ちがう別の語です。", "四角": "「四角」（しかく）は一拍ちがう別の語です。"}, "sentence_index": null, "correct_answer": "地殻"}, "level_3": {"options": [{"text": "地殻", "is_correct": true, "explanation": "岩石をふくむ地球の層なので文に合います。"}, {"text": "空", "is_correct": false, "explanation": "空中には岩石がありません。"}, {"text": "雨", "is_correct": false, "explanation": "水のつぶで、岩石をふくみません。"}, {"text": "夢", "is_correct": false, "explanation": "寝ているときに見るもので、岩石はありません。"}], "explanations": {"地殻": "岩石をふくむ地球の層なので文に合います。", "空": "空中には岩石がありません。", "雨": "水のつぶで、岩石をふくみません。", "夢": "寝ているときに見るもので、岩石はありません。"}, "sentence_index": 6, "correct_answer": "地殻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地殻に電話をかけた。", "explanation": "地殻は人ではないので電話できません。"}, {"text": "地殻を一口食べた。", "explanation": "地殻は食べ物ではありません。"}, {"text": "今日の地殻は晴れだ。", "explanation": "地殻は天気ではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e818d64-970d-4865-aea3-54e56193876e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
