INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35425, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "場所を表す「に」が正しいです（「できる」の場所）。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語で、自動詞「できる」には使えません。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手・並列で、ここでは非文です。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較で、場所を表しません。"}], "correct_answer": "に", "explanations": {"に": "場所を表す「に」が正しいです（「できる」の場所）。", "を": "「を」は目的語で、自動詞「できる」には使えません。", "と": "「と」は相手・並列で、ここでは非文です。", "より": "「より」は比較で、場所を表しません。"}, "error_tags": {"を": "object_marking", "と": "listing", "より": "source_vs_goal"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e818d64-970d-4865-aea3-54e56193876e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35888, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "低い", "is_correct": true, "explanation": "正解。「低い」（ひくい）です。"}, {"text": "広い", "is_correct": false, "explanation": "「広い」（ひろい）は一拍ちがう別の語です。"}, {"text": "憎い", "is_correct": false, "explanation": "「憎い」（にくい）は一拍ちがう別の語です。"}, {"text": "ひどい", "is_correct": false, "explanation": "「ひどい」（ひどい）は一拍ちがう別の語です。"}], "explanations": {"低い": "正解。「低い」（ひくい）です。", "広い": "「広い」（ひろい）は一拍ちがう別の語です。", "憎い": "「憎い」（にくい）は一拍ちがう別の語です。", "ひどい": "「ひどい」（ひどい）は一拍ちがう別の語です。"}, "sentence_index": null, "correct_answer": "低い"}, "level_3": {"options": [{"text": "低い", "is_correct": true, "explanation": "声の高さが少ないことを表すので文に合います。"}, {"text": "赤い", "is_correct": false, "explanation": "色を表し、声には使いません。"}, {"text": "四角い", "is_correct": false, "explanation": "形を表し、声には使いません。"}, {"text": "せまい", "is_correct": false, "explanation": "場所の広さを表し、声には使いません。"}], "explanations": {"低い": "声の高さが少ないことを表すので文に合います。", "赤い": "色を表し、声には使いません。", "四角い": "形を表し、声には使いません。", "せまい": "場所の広さを表し、声には使いません。"}, "sentence_index": 0, "correct_answer": "低い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このカレーは低い味がする。", "explanation": "味には「低い」を使いません。"}, {"text": "低い色のシャツを着た。", "explanation": "色の高さという意味では使いません。"}, {"text": "この本は低いページが多い。", "explanation": "ページ数に「低い」は使いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e818d64-970d-4865-aea3-54e56193876e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35888, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は声が低いだった。", "corrected_sentence": "父は声が低かった。", "error_description": "活用の誤り：い形容詞の過去形は「低いだった」ではなく「低かった」です。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "低い", "is_correct": true, "explanation": "名詞「声」を修飾するので辞書形（連体形）の「低い」です。"}, {"text": "低く", "is_correct": false, "explanation": "連用形で、名詞の前には置けません。"}, {"text": "低かった", "is_correct": false, "explanation": "過去形で、お願いの文では不自然です。"}, {"text": "低ければ", "is_correct": false, "explanation": "条件形で、名詞を修飾できません。"}], "correct_form": "低い", "base_form": "低い", "form_label": "活用", "sentence_index": 1, "explanations": {"低い": "名詞「声」を修飾するので辞書形（連体形）の「低い」です。", "低く": "連用形で、名詞の前には置けません。", "低かった": "過去形で、お願いの文では不自然です。", "低ければ": "条件形で、名詞を修飾できません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e818d64-970d-4865-aea3-54e56193876e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
