INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35926, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "耳で聞こえるもの。", "primary_collocate": null, "pronunciation": "おと", "ipa": "oto", "syllable_count": 2, "sentences": [{"text": "外から大きな音が聞こえた。", "target_word": "音", "complexity_tier": "T3", "furigana": "そと おお おと き", "sentence_source": "generated"}, {"text": "ドアの音で目が覚めた。", "target_word": "音", "complexity_tier": "T3", "furigana": "おと め さ", "sentence_source": "generated"}, {"text": "雨の音を聞きながら寝た。", "target_word": "音", "complexity_tier": "T3", "furigana": "あめ おと き ね", "sentence_source": "generated"}, {"text": "この音は何だろう。", "target_word": "音", "complexity_tier": "T3", "furigana": "おと なん", "sentence_source": "generated"}, {"text": "音を小さくしてください。", "target_word": "音", "complexity_tier": "T3", "furigana": "おと ちい", "sentence_source": "generated"}, {"text": "ピアノの音がきれいだ。", "target_word": "音", "complexity_tier": "T3", "furigana": "おと", "sentence_source": "generated"}, {"text": "静かな部屋に時計の音が響く。", "target_word": "音", "complexity_tier": "T3", "furigana": "しず へや とけい おと ひび", "sentence_source": "generated"}, {"text": "変な音がして怖かった。", "target_word": "音", "complexity_tier": "T3", "furigana": "へん おと こわ", "sentence_source": "generated"}, {"text": "音を立てずに歩いた。", "target_word": "音", "complexity_tier": "T3", "furigana": "おと た ある", "sentence_source": "generated"}, {"text": "波の音が好きです。", "target_word": "音", "complexity_tier": "T3", "furigana": "なみ おと す", "sentence_source": "generated"}], "morphological_forms": [{"form": "音色", "label": "派生"}, {"form": "足音", "label": "派生"}, {"form": "物音", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 耳で聞こえる物の響き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a90f5df0-358d-4a0f-a739-7c1352b8d2c